INSERT INTO plants VALUES(6,'Tribulus terrestris','Gokshura','गोक्षुर','गोक्षुर','गोक्षुर','Zygophyllaceae','Mutrala herb used in urinary stones, kidney function support and male vitality.','Dry sandy soils and wastelands.','["fruit","whole plant"]','["madhura","tikta"]','sheeta','madhura','["guru","snigdha"]','{"vata":"reduces","pitta":"balances","kapha":"increases"}','Strengthens mutravaha & shukravaha srotas.','{"Protodioscin", "saponins"}','["diuretic","nephroprotective","androgen_support","antiurolithic"]','Classically used in mutrakrichra and shukra dhatu enhancement.',0,'wild','Gokshura.jpg','2025-11-25 16:50:54','2025-11-25 16:50:54','Ayurveda');
