INSERT INTO plants VALUES(32,'Holarrhena pubescens','Kutaja','कुटज','कुटज','कुटज','Apocynaceae','Tree with bark and seeds used in diarrhea, dysentery and IBS-type complaints.','Grows in deciduous forests and hedges in India.','["bark","seed"]','["tikta","kashaya"]','sheeta','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"reduces"}','Specific krimighna and grahi action in atisara and pravahika.','["conessine","alkaloids"]','["antidiarrheal","antimicrobial","astringent","gut_tonic"]','["Kutaja widely used in atisara and pravahika formulations."]',0,'wild','Kutaja.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
