INSERT INTO plants VALUES(34,'Morinda citrifolia','Noni','नोनी','नॉनी','आश्यफली (प्रादेशिक)','Rubiaceae','Fruit used in some traditional systems for immunity, digestion and joint health.','Coastal regions and tropical islands; now cultivated in South India.','["fruit","leaf"]','["tikta","kashaya"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"balances","kapha":"reduces"}','Immunomodulatory and mild analgesic effects as per traditional usage.','["iridoids","flavonoids"]','["immunomodulator_support","digestive_support","analgesic_support","antioxidant"]','["Used in integrative practice; not a classical dravya but adopted in some Ayurvedic clinics."]',0,'cultivated','Noni.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(35,'Achyranthes aspera','Apamarga','अपामार्ग','अघाडा','अपामार्ग','Amaranthaceae','Common weed used in kshara karma, piles, skin disease and as shirovirechana nasya.','Waste lands, roadsides and fields throughout India.','["whole_plant","seed","root"]','["katu","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"reduces","pitta":"increases","kapha":"reduces"}','Scraping quality on meda and malas with krimighna property.','["saponins","alkaloids"]','["lekhan","anthelmintic","antiinflammatory","astringent"]','["Apamarga widely used in kshara sutra and arsha chikitsa."]',0,'wild','Apamarga.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(36,'Pterocarpus santalinus','Red Sandalwood','रक्तचंदन','रक्तचंदन','रक्तचन्दन','Fabaceae','Red heartwood used for rakta shodhana, pitta pacification and skin conditions.','Native to Andhra region; now restricted and mostly protected.','["heartwood"]','["tikta","kashaya"]','sheeta','madhura','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"balances"}','Acts on blood and skin to reduce inflammation and bleeding.','["santalin_pigments","tannins"]','["blood_purifier_support","cooling","antiinflammatory","skin_support"]','["Rakta chandana is classical dravya in raktapitta and kushtha."]',1,'wild','Red_Sandalwood.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(37,'Cissampelos pareira','Patha','पाठा','पाठा','पाठा','Menispermaceae','Climbing herb whose root is used in diarrhea, fevers and urinary disorders.','Climbs on shrubs and hedges in forest margins.','["root"]','["tikta","kashaya"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"reduces"}','Acts on rasavaha and raktavaha srotas with grahi and jwaraghna action.','["isoquinoline_alkaloids"]','["antidiarrheal","antipyretic_support","diuretic_support","antiinflammatory"]','["Patha listed in laghu panchamula and used in atisara and jwara."]',0,'wild','Patha.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(38,'Hedychium spicatum','Shati','शाठी','शाठी','शाठी','Zingiberaceae','Aromatic rhizome used in respiratory disorders, hiccups and as expectorant.','Grows in Himalayan forests and hill regions.','["rhizome"]','["katu","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"balances","kapha":"reduces"}','Clears kapha from chest and reduces nausea and hiccups.','["essential_oils","sesquiterpenes"]','["expectorant","carminative","antispasmodic","antiinflammatory"]','["Shati is included in shwasahara and kasahara formulations in classics."]',0,'wild','Shati.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
