INSERT INTO plants VALUES(40,'Swertia chirayita','Chirayata','चिरायता','चिरायटा','किराततिक्त','Gentianaceae','Very bitter herb used in fevers, indigestion and as blood purifier.','Temperate Himalayan slopes; now overharvested in wild.','["whole_plant"]','["tikta"]','sheeta','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"reduces"}','Powerful tikta dravya for jwara, amlapitta and skin disorders.','["seco_iridoid_glycosides","xanthones"]','["antipyretic_support","digestive_stimulant","blood_purifier_support","antiinflammatory"]','["Kiratatiktam is a well-known bitter herb for jwara in texts."]',1,'wild','Chirayata.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(41,'Alpinia galanga','Galangal','कुलंजन','कुळंजन','कुलञ्जन','Zingiberaceae','Aromatic rhizome used in respiratory, digestive and throat disorders.','Cultivated in warm, humid regions; rhizomes harvested like ginger.','["rhizome"]','["katu","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"reduces","pitta":"increases","kapha":"reduces"}','Deepana-pachana with kapha-shamaka effect in throat and chest.','["essential_oils","flavonoids"]','["carminative","expectorant","antiinflammatory","antimicrobial"]','["Kulanjana used for swarabhanga and kasa in traditional practice."]',0,'cultivated','Galangal.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(42,'Cyperus scariosus','Nagarmotha (Scariosus)','नागरमोथा','नागरमोथा','नागरमुष्टि','Cyperaceae','Aromatic root used as cooling, digestive and for headache and skin disorders.','Moist grasslands and marshy areas.','["rhizome","root"]','["tikta","kashaya"]','sheeta','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"balances"}','Acts similarly to mustaka with added cooling and aromatic properties.','["essential_oils","sesquiterpenes"]','["carminative","cooling","antiinflammatory","skin_support"]','["Used in perfumery and Ayurveda for daha and atisara."]',0,'wild','Nagarmotha_Scariosus.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(43,'Abies webbiana','Talispatra','तालीसपत्र','तालीसपत्र','तालीसपत्र','Pinaceae','Leaves used in cough, asthma and to flavor herbal preparations.','Himalayan coniferous forests.','["leaf"]','["katu","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"balances","kapha":"reduces"}','Kaphaghna and shwasahara effect, often added to churnas.','["essential_oils"]','["expectorant","bronchodilator_support","antiseptic","digestive_support"]','["Talisapatra used in kasa and shwasa formulations."]',0,'wild','Talispatra.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(44,'Inula racemosa','Pushkarmoola','पुष्करमूल','पुष्करमुळ','पुष्करमूल','Asteraceae','Root used in heart disease, cough, asthma and chest pain.','High altitude Himalayan regions.','["root"]','["katu","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"reduces","pitta":"balances","kapha":"reduces"}','Acts on hridya and pranavaha srotas with shwasahara and pain-relieving action.','["sesquiterpene_lactones","inulin"]','["cardiotonic_support","expectorant","analgesic_support","antiinflammatory"]','["Pushkarmoola is mentioned for hridroga and shwasa in classics."]',0,'wild','Pushkarmoola.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(45,'Solanum nigrum','Black Nightshade','मकोय','ढोबळी भाजी','काकमाची','Solanaceae','Herb whose leaves and berries are used in liver, skin and inflammatory disorders.','Waste lands, gardens and field margins.','["leaf","whole_plant"]','["tikta","kashaya"]','sheeta','katu','["laghu","snigdha"]','{"vata":"balances","pitta":"reduces","kapha":"balances"}','Pitta-pacifying effect on liver and skin with mild analgesic property.','["glycoalkaloids","flavonoids"]','["hepatoprotective_support","antiinflammatory","analgesic_support","skin_support"]','["Kakamachi described in pittaja roga and akshiroga."]',0,'wild','Black_Nightshade.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
