INSERT INTO plants VALUES(47,'Pistacia integerrima','Karkatashringi','कर्कटशृंगी','कर्कटशृंगी','कर्कटशृंगी','Anacardiaceae','Galls used primarily in respiratory conditions with cough and asthma.','Himalayan regions where galls form on Pistacia trees.','["gall"]','["katu","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"balances","kapha":"reduces"}','Kapha-shamaka and balya for respiratory tract.','["tannins","resins"]','["expectorant","bronchodilator_support","astringent","tonic"]','["Karkatashringi is important in bal cough formulations."]',0,'wild','Karkatashringi.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
