INSERT INTO plants VALUES(49,'Hemidesmus indicus','Indian Sarsaparilla','अनंतमूल','उटी','सारीवा / अनन्तमूल','Apocynaceae','Root used as blood purifier, coolant and in skin and urinary disorders.','Grows in plains and light forests across India.','["root"]','["madhura","tikta"]','sheeta','madhura','["laghu","snigdha"]','{"vata":"balances","pitta":"reduces","kapha":"balances"}','Raktashodhaka and pittashamaka with pleasant aroma.','["saponins","essential_oils"]','["blood_purifier_support","cooling","skin_support","urinary_support"]','["Sariva is a prime raktashodhaka dravya in classics."]',0,'wild_and_cultivated','Indian_Sarsaparilla.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(50,'Argyreia speciosa','Vriddhadaru','वृद्धदारु','वृद्धदारी','वृद्धदारु','Convolvulaceae','Climber whose roots are used as rasayana in neuromuscular weakness and infertility.','Found in hedges and forest borders.','["root"]','["madhura","tikta"]','ushna','madhura','["guru","snigdha"]','{"vata":"reduces","pitta":"balances","kapha":"increases"}','Balya and vrishya rasayana for nervous and reproductive systems.','["starch","glycosides"]','["rasayana","aphrodisiac_support","strength_promoting","neuromuscular_support"]','["Vriddhadaru cited as balya and vrishya in classical texts."]',0,'wild','Vriddhadaru.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(51,'Bergenia ligulata','Pashanbhed','पाषाणभेद','पाषाणभेद','पाषाणभेद','Saxifragaceae','Rhizome used for urinary stones and related urinary tract disorders.','Himalayan rocks and crevices.','["rhizome"]','["tikta","kashaya"]','sheeta','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"balances"}','Special prabhava to break or dissolve urinary calculi.','["bergenin","arbutin"]','["antiurolithic","diuretic_support","antiinflammatory","analgesic_support"]','["Pashanbheda is classical dravya for ashmari and mutrakricchra."]',0,'wild','Pashanbhed.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(52,'Mangifera indica','Mango','आम','आंबा','आम्र','Anacardiaceae','Tree whose leaves, bark and fruit are used for digestion, bleeding and cardiac support.','Cultivated widely as fruit tree throughout India.','["leaf","bark","fruit"]','["amla","madhura","kashaya"]','ushna','madhura','["guru","snigdha"]','{"vata":"balances","pitta":"balances","kapha":"increases"}','Ripe fruit is hridya and balya; bark is astringent in diarrhea and bleeding.','["mangiferin","polyphenols"]','["cardiac_support","digestive_tonic","astringent","nutritive"]','["Amra mentioned among phala and in some formulations."]',0,'cultivated','Mango.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(53,'Psoralea corylifolia','Bakuchi','बाबची','बावची','बकुची','Fabaceae','Seeds used mainly in vitiligo and skin disorders, often with external use.','Dry and warm regions; cultivated in some areas.','["seed","oil"]','["katu","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"increases","kapha":"reduces"}','Stimulates melanocyte function and has kushthaghna effect.','["psoralen","bakuchiol"]','["skin_support","repigmentation_support","antimicrobial","antiinflammatory"]','["Bakuchi is key herb in shwitra (vitiligo) management."]',0,'wild_and_cultivated','Bakuchi.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(54,'Acorus calamus','Sweet Flag','वचा','वच्या','वचा','Acoraceae','Rhizome used as medhya, speech-improving and for cough with thick kapha.','Marshes and water edges in temperate and subtropical zones.','["rhizome"]','["katu","tikta"]','ushna','katu','["laghu","tikshna"]','{"vata":"reduces","pitta":"increases","kapha":"reduces"}','Removes kapha from head and neck and improves speech and memory.','["asarone","essential_oils"]','["expectorant","nootropic_support","digestive_stimulant","antispasmodic"]','["Vacha included among medhya and shirovirechana dravyas."]',0,'wild','Sweet_Flag.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(55,'Piper betle','Betel Leaf','पान','पान','ताम्बूल','Piperaceae','Leaf chewed with areca and lime; used for digestion and local antiseptic effect.','Climbing vine cultivated on supports in humid tropical regions.','["leaf"]','["katu","tikta"]','ushna','katu','["laghu","snigdha"]','{"vata":"reduces","pitta":"increases","kapha":"reduces"}','Stimulates saliva, digestion and acts as local antiseptic in mouth.','["essential_oils","chavicol"]','["digestive_stimulant","carminative","local_antiseptic","mild_stimulant"]','["Tambula mentioned in many contexts including post-prandial use and in lepa."]',0,'cultivated','Betel_Leaf.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(56,'Cinnamomum tamala','Indian Bay Leaf','तेजपत्ता','तमालपत्र','तमालपत्र','Lauraceae','Leaf used as aromatic spice in food and as carminative and mild cardiotonic.','Hill forests and plantations in Himalayan region.','["leaf"]','["katu","tikta","madhura"]','ushna','katu','["laghu","snigdha"]','{"vata":"reduces","pitta":"balances","kapha":"reduces"}','Improves flavor and digestion, with hridya effect when used in moderation.','["essential_oils","cinnamaldehyde"]','["carminative","digestive_support","mild_cardiac_support","antioxidant"]','["Tejapatra is part of various masalas and some classical formulations."]',0,'wild_and_cultivated','Indian_Bay_Leaf.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(57,'Hibiscus rosa-sinensis','Hibiscus','जास्वंद','जास्वंद','जपापुष्प','Malvaceae','Ornamental shrub whose flowers and leaves are used for hair, menstrual and pitta disorders.','Garden ornamental throughout tropical regions.','["flower","leaf"]','["madhura","tikta"]','sheeta','madhura','["laghu","snigdha"]','{"vata":"balances","pitta":"reduces","kapha":"balances"}','Cooling and hair-supportive with mild emmenagogue action.','["flavonoids","anthocyanins"]','["cooling","hair_support","menstrual_support","antiinflammatory"]','["Japa pushpa referenced in some texts for rakta-pitta and hair preparations."]',0,'cultivated','Hibiscus.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(58,'Argemone mexicana','Mexican Poppy','पीला धतूरा (स्वर्णक्षीरी)','पिवळा डाटूरा','स्वर्णक्षीरी','Papaveraceae','Latex-bearing herb used cautiously in skin and liver conditions.','Waste lands and roadsides; considered weed and mildly toxic.','["latex","seed"]','["tikta","katu"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"reduces"}','Used in small, controlled doses by experts for stubborn skin diseases.','["alkaloids","sanguinarine"]','["kusthaghna_support","hepatoprotective_support","antimicrobial"]','["Swarna kshiri referred to in some nighantus with strict caution."]',0,'wild','Mexican_Poppy.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(59,'Calotropis procera','Arka','आक','रूई','अर्क','Apocynaceae','Latex-rich shrub used in vata disorders, skin diseases and in panchakarma as kshara.','Dry and wastelands throughout India.','["latex","leaf","root_bark"]','["katu","tikta"]','ushna','katu','["laghu","tikshna"]','{"vata":"reduces","pitta":"increases","kapha":"reduces"}','Strong ushna and tikshna actions used only in carefully processed form.','["cardenolides","resins"]','["counterirritant","digestive_stimulant","kusthaghna_support","vata_shamaka_support"]','["Arka used in shodhana procedures and specific external therapies."]',0,'wild','Arka.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(60,'Datura metel','Datura','धतूरा','धतूरा','धत्तूर','Solanaceae','Toxic plant whose processed seeds and leaves are used in asthma and pain disorders by experts.','Waste lands and disturbed soils; shrubby growth.','["seed","leaf"]','["tikta","katu"]','ushna','katu','["laghu","tikshna"]','{"vata":"reduces","pitta":"increases","kapha":"reduces"}','Contains anticholinergic tropane alkaloids; used only after proper shodhana.','["atropine","scopolamine"]','["bronchodilator_support","analgesic_support","antispasmodic"]','["Dhattura referenced in toxicology and shwasa roga with strict shodhana rules."]',0,'wild','Datura.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
INSERT INTO plants VALUES(61,'Boerhavia erecta','Erect Boerhavia','छोटी पुनर्नवा','लहान पुनर्नवा','लघु पुनर्नवा','Nyctaginaceae','Related species to Punarnava with similar but milder diuretic and antiinflammatory effects.','Waste land and field margins in warm regions.','["whole_plant","root"]','["kashaya","tikta"]','ushna','katu','["laghu","ruksha"]','{"vata":"balances","pitta":"reduces","kapha":"reduces"}','Used in some regional traditions as punarnava substitute.','["flavonoids","alkaloids"]','["diuretic_support","antiinflammatory","hepatoprotective_support"]','["Recognized in regional practice as a punarnava equivalent."]',0,'wild','Boerhavia_Erecta.jpg','2025-11-25 17:42:24','2025-11-25 17:42:24','Ayurveda');
