INSERT INTO diseases VALUES(1,'Anxiety and Stress','चिंता व तनाव','चिंता व ताण','mental_health','Chinta',NULL,NULL,'Persistent worry, restlessness and stress with disturbed sleep.','["restlessness","racing thoughts","poor sleep","palpitations"]','["chronic stress","work pressure","emotional trauma"]','{"vata":"vitiated","pitta":"mildly_vitiated","kapha":"reduced"}','{"mano_dhatu":"primary","majja_dhatu":"secondary"}','moderate',1,'["adopt regular sleep schedule","practice relaxation and breathing","limit stimulants like caffeine"]','{"favour":["warm light meals","ghee in moderation","herbal teas like brahmi or jatamansi"],"avoid":["excess coffee","refined sugar","heavy late-night meals"]}','2025-11-25 16:50:54',NULL);
INSERT INTO diseases VALUES(2,'Memory Weakness','स्मरण शक्ति दुर्बलता','स्मरण कमी','neurological','Smriti bhramsha',NULL,NULL,'Reduced ability to recall recent events, difficulty concentrating and mental fatigue.','["forgetfulness","low concentration","mental fatigue"]','["chronic stress","sleep deprivation","aging"]','{"vata":"vitiated","pitta":"balanced","kapha":"slightly_reduced"}','{"majja_dhatu":"primary","rasa_dhatu":"secondary"}','mild',1,'["ensure adequate sleep","mental exercises","regular meditation"]','{"favour":["nuts and seeds in moderation","ghee and milk if tolerated","fresh fruits"],"avoid":["very dry foods","skipping meals","excess screen time at night"]}','2025-11-25 16:50:54',NULL);
INSERT INTO diseases VALUES(3,'Recurrent Fever','बार-बार बुखार','पुन्हा पुन्हा ताप','infectious','Punarbhu Jwara',NULL,NULL,'Episodes of raised body temperature occurring repeatedly over weeks or months.','["repeated episodes of fever","chills","body ache","fatigue"]','["recurrent infections","low immunity","incomplete recovery from prior illness"]','{"vata":"vitiated","pitta":"vitiated","kapha":"mildly_vitiated"}','{"rakta_dhatu":"primary","ras_dhatu":"secondary"}','moderate',0,'["complete previous course of treatment","adequate post-illness rest","maintain hygiene and hydration"]','{"favour":["light khichdi","warm herbal decoctions","adequate fluids"],"avoid":["very oily foods","cold drinks and ice cream","heavy fried meals during recovery"]}','2025-11-25 16:50:54',NULL);
INSERT INTO diseases VALUES(4,'Chronic Liver Disorder','दीर्घकालिक यकृत विकार','दीर्घकालीन यकृत विकार','hepatic','Yakrit vikara',NULL,NULL,'Long-standing disturbance in liver function with fatigue, poor digestion and heaviness.','["fatigue","loss of appetite","abdominal heaviness","mild jaundice in some cases"]','["alcohol misuse","fatty diet","viral hepatitis","metabolic syndrome"]','{"pitta":"vitiated","kapha":"vitiated","vata":"secondary"}','{"rakta_dhatu":"primary","mamsa_dhatu":"secondary"}','chronic',1,'["avoid alcohol","maintain healthy body weight","regular physical activity"]','{"favour":["light easily digestible food","bitter green vegetables","adequate water"],"avoid":["alcohol","very oily and fried food","excessive refined sugar"]}','2025-11-25 16:50:54',NULL);
INSERT INTO diseases VALUES(5,'Chronic Skin Disease','दीर्घकालिक त्वचा रोग','जिद्दी त्वचा विकार','dermatological','Kushtha',NULL,NULL,'Long-standing skin disorder with itching, discoloration, scaling or thickening of skin.','["itching","redness or discoloration","scaling","dry or thickened skin"]','["immune imbalance","chronic inflammation","exposure to irritants"]','{"pitta":"vitiated","kapha":"vitiated","vata":"secondary"}','{"rakta_dhatu":"primary","mamsa_dhatu":"secondary"}','chronic',0,'["avoid known triggers","maintain skin hygiene","reduce stress"]','{"favour":["light non-spicy diet","bitter vegetables like neem leaves preparations","adequate hydration"],"avoid":["very spicy food","fermented food","alcohol"]}','2025-11-25 16:50:54',NULL);
INSERT INTO diseases VALUES(6,'Ischemic Heart Disease','हृदय में रक्तसंचार की कमी','हृदयातील रक्तपुरवठा कमी','cardiovascular','Hridroga',NULL,NULL,'Reduced blood flow to heart muscle causing chest discomfort or breathlessness on exertion.','["chest discomfort","breathlessness on exertion","easy fatigue"]','["atherosclerosis","hypertension","diabetes","smoking","sedentary lifestyle"]','{"vata":"vitiated","kapha":"vitiated","pitta":"secondary"}','{"rakta_dhatu":"primary","mamsa_dhatu":"primary"}','severe',1,'["stop smoking","control blood pressure and blood sugar","regular gentle exercise under medical guidance"]','{"favour":["light low-fat diet","foods rich in natural antioxidants","controlled salt intake"],"avoid":["trans fats","smoking","very salty and fried food"]}','2025-11-25 16:50:54',NULL);
INSERT INTO diseases VALUES(7,'Urinary Stones','मूत्र पथरी','मूत्र पथरी','urinary','Ashmari',NULL,NULL,'Stone formation in kidneys or urinary tract leading to colicky pain and burning urination.','["flank pain","colicky abdominal pain","burning urination","blood in urine in some cases"]','["low water intake","high salt intake","metabolic imbalance"]','{"vata":"vitiated","pitta":"vitiated","kapha":"contributing"}','{"mutra_vaha_srotas":"primary","rakta_dhatu":"secondary"}','moderate',1,'["increase daily water intake","avoid holding urine","regular physical activity"]','{"favour":["adequate plain water","citrate containing fruits in moderation","light food"],"avoid":["very salty food","excess animal protein","dehydration"]}','2025-11-25 16:50:54',NULL);
INSERT INTO diseases VALUES(8,'Menstrual Irregularity','मासिक धर्म अनियमितता','मासिक पाळी अनियमित','gynecological','Artava vyapad',NULL,NULL,'Irregular menstrual cycles with variable flow, cramps or premenstrual discomfort.','["irregular cycle length","variable flow","cramps","premenstrual discomfort"]','["hormonal imbalance","stress","sudden weight gain or loss"]','{"vata":"vitiated","pitta":"vitiated","kapha":"variable"}','{"rakta_dhatu":"primary","artava_dhatu":"primary"}','moderate',1,'["maintain regular sleep and food timings","manage stress","moderate exercise"]','{"favour":["warm light meals","iron-rich foods if needed","adequate hydration"],"avoid":["skipping meals","excess caffeine","very cold foods around menses"]}','2025-11-25 16:50:54',NULL);
