INSERT INTO diseases VALUES(151,'Homeopathic Acute Grief and Emotional Upset','होम्योपैथिक तीव्र शोक और भावनात्मक तनाव','होमिओपॅथिक तीव्र दु:ख आणि भावनिक ताण','homeopathy_psych_chronic',NULL,NULL,NULL,'Recent bereavement or strong emotional shock with sighing, sobbing and mood swings.','["crying_spells","lump_in_throat_sensation","mood_swings","sleep_disturbance","loss_of_appetite"]','["bereavement","relationship_breakup","sudden_life_change","acute_emotional_shock"]','["not_tagged_for_homeopathy"]','["not_tagged_for_homeopathy"]','moderate',1,'["seek_emotional_and_social_support","consider_counseling_if_needed","practice_relaxation_or_mindfulness"]','["regular_small_meals","adequate_fluids","avoid_using_alcohol_or_junk_food_for_coping"]','2025-12-02 17:37:24',NULL);
INSERT INTO diseases VALUES(152,'Homeopathic Nerve Injury and Shooting Pain','होम्योपैथिक नसों की चोट और चुभन वाला दर्द','होमिओपॅथिक नस दुखापत आणि झटका देणारी वेदना','homeopathy_neurologic',NULL,NULL,NULL,'Pain in areas rich in nerves after crush injuries or surgery with radiating, shooting character.','["sharp_shooting_pain","tingling","burning_sensation","sensitivity_at_fingertips_or_spine"]','["trauma","surgery","repetitive_strain","nerve_entrapment"]','["not_tagged_for_homeopathy"]','["not_tagged_for_homeopathy"]','moderate',0,'["protect_affected_area","follow_physio_or_rehab_programs","avoid_repetitive_strain"]','["nourishing_balanced_diet","avoid_smoking","avoid_excess_alcohol"]','2025-12-02 17:37:24',NULL);
INSERT INTO diseases VALUES(153,'Homeopathic Local Wound and Slow Healing','होम्योपैथिक घाव और धीमी भरपाई','होमिओपॅथिक जखम आणि हळू भरून येणे','homeopathy_dermatologic',NULL,NULL,NULL,'Shallow wounds, cuts or abrasions that are slow to heal or tend to inflame.','["persistent_soreness","delayed_healing","mild_discharge","local_redness"]','["repeated_trauma","local_infection","poor_local_care","underlying_diabetes_or_anemia"]','["not_tagged_for_homeopathy"]','["not_tagged_for_homeopathy"]','moderate',1,'["maintain_wound_hygiene","protect_from_friction","control_diabetes_and_anemia"]','["protein_rich_foods","adequate_vitamins_and_minerals","avoid_smoking_to_support_healing"]','2025-12-02 17:37:24',NULL);
INSERT INTO diseases VALUES(154,'Homeopathic Chronic Sinus Catarrh','होम्योपैथिक जीर्ण साइनस नज़ला','होमिओपॅथिक जुनाट सायनस नजला','homeopathy_respiratory_catarrh',NULL,NULL,NULL,'Chronic sinus complaints with thick, stringy mucus and post-nasal drip.','["headache","facial_pressure","sticky_nasal_discharge","post_nasal_drip","recurrent_cough"]','["allergy","repeated_sinus_infections","structural_nasal_issues","irritant_exposure"]','["not_tagged_for_homeopathy"]','["not_tagged_for_homeopathy"]','chronic',1,'["avoid_smoking_and_pollution","manage_allergies","use_steam_inhalation_if_advised"]','["simple_less_processed_diet","adequate_warm_fluids","limit_very_cold_food_and_drinks"]','2025-12-02 17:37:24',NULL);
INSERT INTO diseases VALUES(155,'Homeopathic Chronic Skin Eruption and Itching','होम्योपैथिक पुरानी त्वचा विकृति और खुजली','होमिओपॅथिक जुनाट त्वचा विकार आणि खाज','homeopathy_skin_chronic',NULL,NULL,NULL,'Longstanding superficial skin eruptions with itching and burning in constitutional cases.','["itchy_rash","dryness_or_oozing","recurrent_flare_ups","worse_from_heat_in_some_people"]','["genetic_tendency","irritant_exposure","allergen_exposure","metabolic_imbalance","stress"]','["not_tagged_for_homeopathy"]','["not_tagged_for_homeopathy"]','chronic',1,'["avoid_harsh_soaps_and_detergents","avoid_known_allergens","keep_skin_moisturized"]','["simple_less_processed_food","adequate_water_intake","maintain_healthy_weight_and_metabolic_control"]','2025-12-02 17:37:24',NULL);
INSERT INTO diseases VALUES(156,'Homeopathic Low-grade Fever and Inflammatory Tendency','होम्योपैथिक कम दर्ज़े का बुखार और सूजन प्रवृत्ति','होमिओपॅथिक सौम्य ताप आणि दाह प्रवृत्ती','homeopathy_fever_lowgrade',NULL,NULL,NULL,'Recurrent low-grade fever or early inflammatory states where tissue salts and supportive remedies are sometimes considered.','["recurrent_low_grade_fever","fatigue","vague_body_aches","early_local_redness_or_swelling"]','["chronic_low_grade_infection","autoimmune_process","post_viral_state","poor_recovery_from_illness"]','["not_tagged_for_homeopathy"]','["not_tagged_for_homeopathy"]','chronic',0,'["ensure_full_medical_evaluation","allow_adequate_rest","manage_stress_and_sleep"]','["nutritious_diet_with_enough_protein","adequate_micronutrients","follow_medical_dietary_guidance_if_given"]','2025-12-02 17:37:24',NULL);
