INSERT INTO preparations_fts_content VALUES(1,'Jamun Seed Churna','जामुन बीज चूर्ण','जांभुळ बी चूर्ण','Jambu Bija Churna','powder','Jamun seed powder is used traditionally in Ayurveda as a supportive measure in Madhumeha/Type 2 Diabetes and related metabolic patterns, along with diet, lifestyle and medical treatment.');
INSERT INTO preparations_fts_content VALUES(2,'Safed Musli Rasayana Granules','सफेद मूसली रसायन ग्रेन्यूल्स','सफेद मूसळी रसायन ग्रॅन्यूल्स','Musali Rasayana (simplified)','granules','Safed Musli-based granules used traditionally as Rasayana and balya for strength, vitality and reproductive support, under supervision and with attention to metabolic status.');
INSERT INTO preparations_fts_content VALUES(3,'Ashoka Bark Decoction','अशोक की छाल का काढ़ा','अशोक सालीचा काढा','Ashoka Kwatha (simplified)','decoction','Traditional Ashoka bark decoction used in Ayurveda for support in menstrual and gynecological complaints, under qualified supervision.');
INSERT INTO preparations_fts_content VALUES(4,'Barley Water','जौ का पानी','बार्लीचे पाणी','Yava Jala (Yavodaka)','herbal_water','Traditional barley water preparation used in Ayurveda for digestion, metabolic and urinary support, often in Kapha/Medo and Mutravaha conditions.');
INSERT INTO preparations_fts_content VALUES(5,'Palash Flower Decoction','पलाश पुष्प काढ़ा','पळस फुलांचा काढा','Palasha Pushpa Kwatha (simplified)','decoction','Palash flower decoction is employed traditionally in krimi and certain Rakta/Pitta-related conditions; use is individualized and requires supervision.');
INSERT INTO preparations_fts_content VALUES(6,'Gudmar Leaf Churna','गुड़मार पत्ती चूर्ण','गुढमार पानांचा चूर्ण','Meshashringi Patra Churna (simplified)','powder','Gudmar leaf powder is used in Ayurveda as a supportive measure in Madhumeha/Type 2 diabetes and appetite for sweets, always along with diet, lifestyle and medical care.');
INSERT INTO preparations_fts_content VALUES(7,'Tagara Sleep Support Powder','टगर निद्रा चूर्ण','टगर निद्रा चूर्ण','Tagara Churna (simplified)','powder','Tagara powder is traditionally used as mild sedative/anxiolytic support in Ayurveda. Dose is individualized and may interact with other sedatives; use under supervision.');
INSERT INTO preparations_fts_content VALUES(8,'Bitter Gourd Juice','करेला का रस','कारल्याचा रस','Karavella Swarasa (simplified)','juice','Fresh Bitter Gourd juice is a strong preparation traditionally used in small doses as metabolic support in diabetes-related contexts; care is required to avoid excessive use or hypoglycemia.');
INSERT INTO preparations_fts_content VALUES(9,'Bottle Gourd Light Soup','लौकी का हल्का सूप','दुधी भोपळ्याचे हलके सूप','Alabu Supa (dietary form)','medicated_food','Bottle Gourd light soup is used as a part of Ayurvedic-style light diet for certain heart, obesity and Pitta-related conditions; emphasis is on proper selection of fresh gourds (not overly bitter) and medical supervision if there are cardiac issues.');
INSERT INTO preparations_fts_content VALUES(10,'Indian Borage Leaf Decoction','अजवाइन पत्ती काढ़ा','ओव्याच्या पानांचा काढा','Indian Borage Kwatha (home-style)','decoction','Indian Borage leaf decoction is a common household remedy for mild cough/cold and digestive discomfort, typically used short-term and alongside appropriate medical care where needed.');
INSERT INTO preparations_fts_content VALUES(11,'Triphala Churna','त्रिफला चूर्ण','त्रिफळा चूर्ण','Triphala Churna','powder','Classical Triphala powder used traditionally to support digestion, bowel regularity, eye health and Rasayana actions. Not a substitute for medical care.');
INSERT INTO preparations_fts_content VALUES(12,'Turmeric Milk','हल्दी वाला दूध','हळदीचे दूध','Haridra Ksheerapaka (simple form)','medicated_milk','Traditional household preparation used in Ayurveda and folk practice for skin support, minor respiratory complaints and general Rasayana benefit. Not a replacement for medical treatment.');
INSERT INTO preparations_fts_content VALUES(13,'Ajwain Digestive Water','अजवाइन का पानी','ओव्याचे पाणी','Yavani Jala (simple household form)','herbal_water','Traditional carminative water used in Indian households for gas, bloating and mild colicky discomfort. Dose and duration individualized.');
INSERT INTO preparations_fts_content VALUES(14,'Ashwagandha Rasayana Lehya','अश्वगंधा रसायन लेह्य','अश्वगंधा रसायन लेह्य','Ashvagandhadi Lehya (simplified)','lehya','Classical Rasayana-type preparation used for debility and Vata disorders; dosing and duration must be individualized.');
INSERT INTO preparations_fts_content VALUES(15,'Shankhpushpi Decoction','शंखपुष्पी काढ़ा','शंखपुष्पी काढा','Shankhapushpi Kwatha','decoction','Used traditionally as Medhya Rasayana for memory and calmness along with diet, sleep and lifestyle measures.');
INSERT INTO preparations_fts_content VALUES(16,'Indian Coleus Root Decoction','भारतीय कोलेयस मूल काढ़ा','भारतीय कोलेयस मुळाचा काढा','Makandi Kwatha (simplified)','decoction','Used in some Ayurvedic contexts for cardiac and respiratory support; must be supervised due to hemodynamic effects.');
INSERT INTO preparations_fts_content VALUES(17,'Shallaki Resin Powder','सलई गुग्गुलु चूर्ण','सलई गुग्गुळ चूर्ण','Shallaki Churna','powder','Used traditionally as supportive agent in joint and inflammatory conditions; not a replacement for rheumatology care.');
INSERT INTO preparations_fts_content VALUES(18,'Drumstick Leaf Soup','सहजन पत्ता सूप','शेवग्याच्या पानांचे सूप','Shigru Patra Supa (dietary)','medicated_food','Moringa/Drumstick leaves are rich in micronutrients and used in Ayurveda-inspired diets for weakness, anemia and metabolic support.');
INSERT INTO preparations_fts_content VALUES(19,'Pomegranate Rind Decoction','अनार छिलका काढ़ा','डाळिंब साल काढा','Dadima Tvak Kwatha','decoction','Astringent, gut-supportive decoction used classically in some Atisara/Grahani and cardiac-supportive contexts.');
INSERT INTO preparations_fts_content VALUES(20,'Lemon Digestive Drink','नींबू पाचन पेय','लिंबू पचन पेय','Nimbuka Peya (simplified)','herbal_drink','Used as simple digestive aid; should be modified or avoided in individuals with severe hyperacidity or ulcers.');
INSERT INTO preparations_fts_content VALUES(21,'Holy Fig Bark Decoction','पीपल की छाल का काढ़ा','पिंपळ सालीचा काढा','Ashvattha Tvak Kwatha','decoction','Referenced in Ayurvedic context for respiratory and cardiac support; do not substitute for modern cardiology treatment.');
INSERT INTO preparations_fts_content VALUES(22,'Banyan Bark Decoction','वट वृक्ष की छाल का काढ़ा','वड सालीचा काढा','Vatavriksha Kwatha','decoction','Used in some traditional contexts in metabolic and shotha-related conditions; sustainability and proper identification are important.');
INSERT INTO preparations_fts_content VALUES(23,'Coconut Milk Tonic','नारियल दूध टॉनिक','नारळाचे दूध टॉनिक','Narikela Ksheerapaka (simplified)','nutritive_drink','Cooling, nutritive drink often used in Pitta conditions and general weakness; consider Kapha/Medo status and digestion.');
INSERT INTO preparations_fts_content VALUES(24,'Nutmeg Sleep Milk','जायफल निद्रा दूध','जायफळ निद्रा दूध','Jatiphala Ksheera (simplified)','medicated_milk','Traditional home-style support for sleep and digestion; Nutmeg must be used in very small doses due to toxicity risk at higher intake.');
INSERT INTO preparations_fts_content VALUES(25,'Saffron Milk','केसर दूध','केशर दूध','Kumkuma Ksheera','medicated_milk','Classical Rasayana-style milk used in small amounts for mind, heart and complexion support; potent and costly, so doses are small.');
INSERT INTO preparations_fts_content VALUES(26,'Black Cardamom Digestive Decoction','बड़ी इलायची काढ़ा','मोठी वेलची काढा','Brihad Ela Kwatha (simplified)','decoction','Traditional warming aromatic decoction supportive in digestion and mild respiratory discomfort.');
INSERT INTO preparations_fts_content VALUES(27,'Star Anise Digestive Infusion','चक्र फूल पाचन फांटा','चक्रफूल पचन फांटा','Chakra Phala Phanta','herbal_tea','Mild aromatic infusion for post-meal heaviness and gas in some individuals.');
INSERT INTO preparations_fts_content VALUES(28,'Raisin Decoction','किशमिश काढ़ा','किशमिश काढा','Draksha Kashaya (simplified)','decoction','Raisin-based decoction (Draksha) is used traditionally for mild cough, burning and debility; sugar load must be considered in diabetes.');
INSERT INTO preparations_fts_content VALUES(29,'Dates Energy Drink','खजूर ऊर्जा पेय','खजूर ऊर्जा पेय','Khajura Ksheerapaka (simplified)','nutritive_drink','Nourishing sweet drink commonly used for weakness; must be used carefully in diabetes or obesity.');
INSERT INTO preparations_fts_content VALUES(30,'Black Cumin Seed Powder','कलौंजी बीज चूर्ण','काळे जिरे बी चूर्ण','Krishna Jiraka Churna (simplified)','powder','Used as spice-based support in digestion and metabolism; may interact with metabolic medications in some individuals.');
INSERT INTO preparations_fts_content VALUES(31,'Garden Cress Seed Milk','हलिम बीज दूध','हालिम बीज दूध','Chandrashura Ksheerapaka (popular form)','medicated_milk','Known home-style preparation for iron and bone support; may aggravate Pitta or cause gastric discomfort in some individuals.');
INSERT INTO preparations_fts_content VALUES(32,'Khadira Skin Wash Decoction','खैर त्वचा धुलाई काढ़ा','खैर त्वचा धुण्याचा काढा','Khadira Kwatha (external)','decoction','Khadira decoction is traditionally used as external wash in chronic skin conditions along with internal management.');
INSERT INTO preparations_fts_content VALUES(33,'Vetiver Cooling Infusion','खस ठंडा पेय','खस थंड पेय','Ushira Jala / Ushira Phanta','herbal_water','Ushira (Vetiver) infused water is a classical cooling drink for Pitta and heat conditions; hygiene and source quality of roots are important.');
INSERT INTO preparations_fts_content VALUES(34,'Brahmi Memory Decoction','ब्राह्मी स्मरण शक्ति काढ़ा','ब्राह्मी स्मरणशक्ती काढा','Brahmi Kwatha (Medhya Rasayana)','decoction','Brahmi decoction is traditionally used as Medhya (brain-supportive) Rasayana along with proper sleep, diet and lifestyle; not a replacement for neurological care.');
INSERT INTO preparations_fts_content VALUES(35,'Gotu Kola Leaf Decoction','मंडूकपर्णी पत्ती काढ़ा','मांडूकपर्णी पानांचा काढा','Mandukaparni Kwatha (simplified)','decoction','Gotu Kola is used in Ayurveda for Medhya and skin support; dose and duration are individualized by practitioner.');
INSERT INTO preparations_fts_content VALUES(36,'Giloy Stem Decoction','गिलोय का काढ़ा','गुळवेलचा काढा','Guduchi Kwatha','decoction','Guduchi kwatha is classical Rasayana and Jwara-supportive decoction; monitoring is needed in chronic conditions.');
INSERT INTO preparations_fts_content VALUES(37,'Neem Leaf Decoction','नीम पत्ती काढ़ा','कडुनिंब पानांचा काढा','Nimba Patra Kwatha','decoction','Neem decoction is a strong, bitter preparation used classically for skin, Pitta and Kapha conditions; internal use must be supervised.');
INSERT INTO preparations_fts_content VALUES(38,'Arjuna Bark Decoction','अर्जुन की छाल का काढ़ा','अर्जुन सालीचा काढा','Arjuna Kwatha','decoction','Arjuna decoction is classical supportive preparation for Hridroga; not a substitute for modern cardiac interventions.');
INSERT INTO preparations_fts_content VALUES(39,'Gokshura Seed Decoction','गोक्षुरु बीज काढ़ा','गोक्षुर बी काढा','Gokshuradi Kwatha (simplified single-herb)','decoction','Traditionally used in urinary and reproductive support; hydration and medical evaluation remain essential.');
INSERT INTO preparations_fts_content VALUES(40,'Punarnava Root Decoction','पुनर्नवा मूल काढ़ा','पुनर्नवा मुळाचा काढा','Punarnava Kwatha','decoction','Punarnava kwatha is classical Mutravaha and Shotha-supportive; monitoring kidney function and electrolytes via modern medicine is important.');
INSERT INTO preparations_fts_content VALUES(41,'Shatavari Medicated Milk','शतावरी क्षीरपाक','शतावरी क्षीरपाक','Shatavari Ksheerapaka','medicated_milk','Classically used as Rasayana, especially in women’s health and Pitta/Vata conditions; lactose intolerance and digestive capacity must be considered.');
INSERT INTO preparations_fts_content VALUES(42,'Licorice Gastric Support Decoction','यष्टिमधु जठर काढ़ा','जेष्ठमध जठर काढा','Yashtimadhu Kwatha','decoction','Yashtimadhu is classical for throat and gastric comfort; care is needed in hypertension, edema or heart failure due to potential salt/water retention.');
