INSERT INTO preparations_fts_content VALUES(122,'Ferrum Phos 6X Tablets','फेरम फॉस 6X टेबलेट','फेरम फॉस 6X गोळ्या','Ferrum phosphoricum 6X (tissue salt)','trituration_tablet','Used as supportive tissue salt in low-grade inflammatory states and mild anemia tendency (not a replacement for medical treatment).');
INSERT INTO preparations_fts_content VALUES(123,'Kali Bichrom 30C Oral Globules','काली बाइक्रोम 30C गोलियां','काली बायक्रोम 30C गोळ्या','Kalium bichromicum 30C','globules','Used in homeopathy for thick stringy mucus and sinus catarrh pictures.');
INSERT INTO preparations_fts_content VALUES(124,'Natrum Mur 30C Oral Globules','नैट्रम म्यूर 30C गोलियां','नॅट्रम म्यूर 30C गोळ्या','Natrium muriaticum 30C','globules','Used for chronic headache and grief-tendency states in homeopathic tradition.');
INSERT INTO preparations_fts_content VALUES(125,'Sulphur 30C Oral Globules','सल्फर 30C गोलियां','सल्फर 30C गोळ्या','Sulphur 30C','globules','Used as a constitutional remedy for chronic skin and heat patterns when indicated.');
INSERT INTO preparations_fts_content VALUES(126,'Hepar Sulph 30C Oral Globules','हेपर सल्फ 30C गोलियां','हेपर सल्फ 30C गोळ्या','Hepar sulphuris calcareum 30C','globules','Used in homeopathy for painful inflamed lesions with tendency to suppurate.');
INSERT INTO preparations_fts_content VALUES(127,'Lycopodium 30C Oral Globules','लायकॉपोडियम 30C गोलियां','लायकॉपोडियम 30C गोळ्या','Lycopodium clavatum 30C','globules','Used for bloating, gas and anticipatory anxiety patterns in homeopathic practice.');
INSERT INTO preparations_fts_content VALUES(128,'Sepia 30C Oral Globules','सेपिया 30C गोलियां','सेपिया 30C गोळ्या','Sepia officinalis 30C','globules','Used in specific pelvic and mood patterns in homeopathic tradition.');
INSERT INTO preparations_fts_content VALUES(129,'Silicea 30C Oral Globules','सिलिसिया 30C गोलियां','सिलिसिया 30C गोळ्या','Silicea terra 30C','globules','Used in slow-healing, chronic suppuration and tissue weakness pictures.');
INSERT INTO preparations_fts_content VALUES(130,'Arsenicum Album 30C Oral Globules','आर्सेनिकम एल्बम 30C गोलियां','आर्सेनिकम अल्बम 30C गोळ्या','Arsenicum album 30C','globules','Used for anxiety with restlessness and digestive irritation patterns in homeopathic practice.');
INSERT INTO preparations_fts_content VALUES(131,'Carbo Veg 30C Oral Globules','कार्बो वेज 30C गोलियां','कार्बो वेज 30C गोळ्या','Carbo vegetabilis 30C','globules','Used in homeopathy for flatulence with exhaustion and low vitality states needing fresh air.');
INSERT INTO preparations_fts_content VALUES(132,'Gudmar Kadha','गुडमार का काढ़ा','गुडमार काढा','Meshashringi Kwatha','decoction','Traditional Ayurveda–based decoction useful as supportive care for sugar and metabolic balance. Should not replace prescribed diabetic medication. Monitor sugar levels regularly.');
