INSERT INTO preparations_fts_config VALUES('version',4);
INSERT INTO preparations VALUES(1,'Jamun Seed Churna','जामुन बीज चूर्ण','जांभुळ बी चूर्ण','Jambu Bija Churna','powder','metabolic_support','1) Collect mature Jamun seeds and wash thoroughly. 2) Dry completely in shade and then in gentle sun if needed. 3) Remove any outer pulp remnants. 4) Powder the dried seeds to fine churna. 5) Store in airtight, moisture-free container.','cleaning_tray; drying_arrangement; grinder; airtight_container','Several hours to days for drying; powdering time depends on batch size.','Yield depends on number of seeds; approx. equal to dry weight.','Store in cool, dry, airtight container away from moisture and direct heat.','Typically used within 3–6 months under proper storage conditions.','{"adult":"1–3 g once or twice daily under professional supervision","child":"Only under qualified supervision with individualized dose."}','usually_before_meals_or_as_directed','plain_water_or_as_directed_by_practitioner','Jamun seed powder is used traditionally in Ayurveda as a supportive measure in Madhumeha/Type 2 Diabetes and related metabolic patterns, along with diet, lifestyle and medical treatment.','2025-12-01 14:17:21',NULL,'ayurveda',70);
INSERT INTO preparations VALUES(2,'Safed Musli Rasayana Granules','सफेद मूसली रसायन ग्रेन्यूल्स','सफेद मूसळी रसायन ग्रॅन्यूल्स','Musali Rasayana (simplified)','granules','rasayana_and_strength_support','1) Clean and dry Safed Musli tubers thoroughly. 2) Powder to a coarse/fine consistency as required. 3) Prepare a suitable sweet base (e.g., sugar or jaggery syrup) and mix with the powder to form granules. 4) Dry the granules gently in shade until free-flowing. 5) Store in airtight container.','grinder; mixing_bowl; tray_for_drying; airtight_container','Several hours to a day including drying time.','Yield depends on amount of Safed Musli and sweet base used; typically close to combined dry weight.','Store in a cool, dry place in airtight container away from moisture.','Often used within 3–6 months under proper storage.','{"adult":"5–10 g once or twice daily under professional supervision","child":"only under qualified guidance"}','usually_morning_and_or_evening_after_food','lukewarm_milk_or_lukewarm_water_as_suitable','Safed Musli-based granules used traditionally as Rasayana and balya for strength, vitality and reproductive support, under supervision and with attention to metabolic status.','2025-12-01 14:17:21',NULL,'ayurveda',91);
INSERT INTO preparations VALUES(3,'Ashoka Bark Decoction','अशोक की छाल का काढ़ा','अशोक सालीचा काढा','Ashoka Kwatha (simplified)','decoction','gynecological_support','1) Take coarse powder of Ashoka bark. 2) Add to water in classical proportion (e.g., 1 part coarse powder to 16 parts water, reduce to 1/4), or as guided. 3) Boil gently until reduced; stir intermittently. 4) Filter warm and use as prescribed.','decoction_pot; heating_source; strainer; measuring_cup','30–45 minutes depending on volume.','Typically one dose of 60–120 ml from initial water volume.','Best used fresh and warm; can be kept covered for few hours if needed.','Same-day use recommended unless otherwise specified.','{"adult":"30–60 ml once or twice daily under gynecological supervision","child":"use only if specifically prescribed"}','as_directed_by_practitioner','plain_or_with_suitable_vehicle_as_advised','Traditional Ashoka bark decoction used in Ayurveda for support in menstrual and gynecological complaints, under qualified supervision.','2025-12-01 14:17:21',NULL,'ayurveda',95);
INSERT INTO preparations VALUES(4,'Barley Water','जौ का पानी','बार्लीचे पाणी','Yava Jala (Yavodaka)','herbal_water','digestive_and_metabolic_support','1) Clean and lightly roast or wash barley grains. 2) Boil a measured quantity of barley in several times water until grains are soft and the water becomes slightly viscous. 3) Filter to obtain clear barley water. 4) Cool to lukewarm or room temperature and use as directed.','cooking_pot; heating_source; strainer; measuring_cups','30–45 minutes depending on quantity.','Typically 500–1000 ml barley water from one small batch of grains.','Can be kept covered and used during the same day; refrigerate if stored longer.','Preferably consumed within 12–24 hours.','{"adult":"50–150 ml 2–3 times daily as supportive drink","child":"smaller quantities as suitable under guidance"}','throughout_day_or_as_directed','plain; may be lightly seasoned as per advice','Traditional barley water preparation used in Ayurveda for digestion, metabolic and urinary support, often in Kapha/Medo and Mutravaha conditions.','2025-12-01 14:17:21',NULL,'ayurveda',103);
INSERT INTO preparations VALUES(5,'Palash Flower Decoction','पलाश पुष्प काढ़ा','पळस फुलांचा काढा','Palasha Pushpa Kwatha (simplified)','decoction','krimi_and_skin_support','1) Take dried Palash flowers and clean to remove foreign matter. 2) Prepare coarse powder or use broken flowers. 3) Boil in suitable quantity of water until volume reduces as per kwatha standard. 4) Filter warm and use strictly as advised by practitioner.','decoction_pot; heating_source; strainer; measuring_cup','20–30 minutes.','Single or multiple doses depending on starting volume.','Should be prepared fresh; use same day.','Same-day use recommended.','{"adult":"dose and duration only as per professional prescription","child":"use only under strict professional supervision"}','as_directed_by_practitioner','plain_or_with_suitable_vehicle_as_prescribed','Palash flower decoction is employed traditionally in krimi and certain Rakta/Pitta-related conditions; use is individualized and requires supervision.','2025-12-01 14:17:21',NULL,'ayurveda',106);
INSERT INTO preparations VALUES(6,'Gudmar Leaf Churna','गुड़मार पत्ती चूर्ण','गुढमार पानांचा चूर्ण','Meshashringi Patra Churna (simplified)','powder','metabolic_support','1) Collect Gudmar leaves from identified plants and wash thoroughly. 2) Shade-dry the leaves until completely crisp and moisture-free. 3) Powder the dried leaves to fine churna. 4) Sieve if required to get uniform powder. 5) Store in airtight container away from moisture.','cleaning_tray; drying_surface; grinder; sieve; airtight_container','1–2 days for proper drying depending on climate; powdering time is short.','Close to dry weight of leaves after cleaning and drying.','Store in cool, dry place in airtight container away from direct sunlight.','Typically used within 3–6 months under proper storage conditions.','{"adult":"1–3 g once or twice daily under professional supervision, especially in diabetes","child":"only under expert supervision with individualized dose"}','usually_before_meals_or_as_directed','plain_water_or_as_directed_by_practitioner','Gudmar leaf powder is used in Ayurveda as a supportive measure in Madhumeha/Type 2 diabetes and appetite for sweets, always along with diet, lifestyle and medical care.','2025-12-01 14:17:21',NULL,'ayurveda',108);
INSERT INTO preparations VALUES(7,'Tagara Sleep Support Powder','टगर निद्रा चूर्ण','टगर निद्रा चूर्ण','Tagara Churna (simplified)','powder','sleep_and_anxiety_support','1) Clean Tagara rhizomes/roots and cut into small pieces. 2) Dry thoroughly in shade, avoiding high heat. 3) Powder to a moderately fine churna. 4) Sieve if needed and store in airtight container. 5) Use in very small, supervised doses.','knife; drying_tray; grinder; sieve; airtight_container','Several hours to day(s) for drying; grinding time is short.','Close to dry root weight after cleaning and drying.','Keep in airtight container in a cool, dry place away from strong light.','Commonly used within 6 months if stored well.','{"adult":"0.5–2 g at bedtime under professional supervision","child":"not routinely used; only under expert guidance"}','bedtime','lukewarm_water_or_as_directed','Tagara powder is traditionally used as mild sedative/anxiolytic support in Ayurveda. Dose is individualized and may interact with other sedatives; use under supervision.','2025-12-01 14:17:21',NULL,'ayurveda',109);
INSERT INTO preparations VALUES(8,'Bitter Gourd Juice','करेला का रस','कारल्याचा रस','Karavella Swarasa (simplified)','juice','metabolic_support','1) Select fresh, tender Bitter Gourd fruits and wash thoroughly. 2) Remove seeds if large and chop fruits into small pieces. 3) Crush/blend with small quantity of water to obtain juice. 4) Filter if required and consume immediately in small, supervised quantity.','knife; cutting_board; juicer_or_blender; strainer; measuring_cup','15–20 minutes.','Quantity depends on number of fruits; typically 30–50 ml per person.','Use fresh; do not store for long durations.','Use immediately; discard after a few hours.','{"adult":"10–30 ml once daily on empty stomach or before food under strict supervision","child":"use only under expert guidance"}','morning_empty_stomach_or_as_directed','plain_or_diluted_with_small_amount_of_water','Fresh Bitter Gourd juice is a strong preparation traditionally used in small doses as metabolic support in diabetes-related contexts; care is required to avoid excessive use or hypoglycemia.','2025-12-01 14:17:21',NULL,'ayurveda',114);
INSERT INTO preparations VALUES(9,'Bottle Gourd Light Soup','लौकी का हल्का सूप','दुधी भोपळ्याचे हलके सूप','Alabu Supa (dietary form)','medicated_food','cardiac_and_metabolic_support_food','1) Peel and cut tender Bottle Gourd into small cubes after washing. 2) Boil in adequate water until soft. 3) Lightly mash and season with small amount of suitable spice (e.g., cumin, black pepper) and a little salt as appropriate. 4) Avoid heavy oil and frying; keep preparation light and easily digestible. 5) Serve warm as part of meal.','knife; cooking_pot; ladle; masher_or_spoon','20–30 minutes.','2–3 servings depending on quantity of Bottle Gourd used.','Best consumed fresh; refrigerate only if needed for short time.','Use within the same day; preferably within a few hours.','{"adult":"one bowl as part of lunch or dinner in indicated individuals","child":"smaller portion according to appetite"}','with_main_meal','taken_as_part_of_sattvic_light_diet','Bottle Gourd light soup is used as a part of Ayurvedic-style light diet for certain heart, obesity and Pitta-related conditions; emphasis is on proper selection of fresh gourds (not overly bitter) and medical supervision if there are cardiac issues.','2025-12-01 14:17:21',NULL,'ayurveda',115);
INSERT INTO preparations VALUES(10,'Indian Borage Leaf Decoction','अजवाइन पत्ती काढ़ा','ओव्याच्या पानांचा काढा','Indian Borage Kwatha (home-style)','decoction','respiratory_support','1) Pluck a few fresh Indian Borage leaves and wash properly. 2) Tear or cut them and add to water in a small vessel. 3) Boil gently for several minutes until aroma is released and water is reduced slightly. 4) Filter and use warm in small quantities.','small_pot; heating_source; strainer; measuring_cup','10–15 minutes.','One or two small servings (30–60 ml each).','Use fresh; keep covered if using within a few hours.','Same-day use; preferably within a few hours of preparation.','{"adult":"15–30 ml warm, sipped 1–2 times daily during acute phase under guidance","child":"very small quantity and only under professional supervision"}','after_meals_or_as_directed','plain_warm','Indian Borage leaf decoction is a common household remedy for mild cough/cold and digestive discomfort, typically used short-term and alongside appropriate medical care where needed.','2025-12-01 14:17:21',NULL,'ayurveda',125);
INSERT INTO preparations VALUES(11,'Triphala Churna','त्रिफला चूर्ण','त्रिफळा चूर्ण','Triphala Churna','powder','digestive_support','1) Take equal parts by weight of dried fruits of Haritaki, Bibhitaki and Amalaki. 2) Clean and remove foreign material. 3) Powder each fruit separately to fine powder. 4) Sieve if required and mix all three powders thoroughly in equal proportions. 5) Store the mixed powder in airtight container.','grinder_or_pulverizer; sieve; airtight_container; weighing_scale','About 45–60 minutes depending on batch size.','Close to total weight of dried fruits after cleaning.','Store in a cool, dry, airtight container away from moisture.','Commonly used within 3–6 months under proper storage conditions.','{"adult":"3–5 g once or twice daily with suitable anupana","child":"1–2 g once daily under supervision"}','usually_at_bedtime_or_as_directed','lukewarm_water_or_ghee_or_honey_as_suitable','Classical Triphala powder used traditionally to support digestion, bowel regularity, eye health and Rasayana actions. Not a substitute for medical care.','2025-12-01 15:01:41',NULL,'ayurveda',128);
INSERT INTO preparations VALUES(12,'Turmeric Milk','हल्दी वाला दूध','हळदीचे दूध','Haridra Ksheerapaka (simple form)','medicated_milk','respiratory_and_skin_support','1) Take about 150–200 ml milk (or suitable milk alternative). 2) Add 1/4–1/2 teaspoon turmeric powder and mix. 3) Heat gently to near boiling, stirring well. 4) Optionally add a pinch of black pepper and small amount of ghee as advised. 5) Consume warm.','small_pan; heating_source; spoon/measuring_spoon','10–15 minutes.','One serving (150–200 ml).','Use fresh; do not store for later use.','Single serving; discard leftovers.','{"adult":"150–200 ml once daily, usually at night, as suitable","child":"Use lower quantity and only under guidance."}','usually_at_bedtime','plain_or_with_small_amount_of_ghee_or_jaggery_as_suitable','Traditional household preparation used in Ayurveda and folk practice for skin support, minor respiratory complaints and general Rasayana benefit. Not a replacement for medical treatment.','2025-12-01 15:01:41',NULL,'ayurveda',131);
INSERT INTO preparations VALUES(13,'Ajwain Digestive Water','अजवाइन का पानी','ओव्याचे पाणी','Yavani Jala (simple household form)','herbal_water','digestive_support','1) Lightly roast ajwain seeds in a pan until aromatic. 2) Add about 1 teaspoon roasted seeds to 200–250 ml water. 3) Boil gently for several minutes, then allow to steep. 4) Filter when lukewarm. 5) Sip as directed.','small_pan; heating_source; strainer; measuring_spoon','15–20 minutes.','Approx. 200–250 ml herbal water.','Can be kept covered and used within the same day.','Same-day use recommended.','{"adult":"30–60 ml after meals, up to 2–3 times a day as needed","child":"Use only with professional guidance and adjusted dose."}','after_meals','plain_lukewarm','Traditional carminative water used in Indian households for gas, bloating and mild colicky discomfort. Dose and duration individualized.','2025-12-01 15:01:41',NULL,'ayurveda',136);
INSERT INTO preparations VALUES(14,'Ashwagandha Rasayana Lehya','अश्वगंधा रसायन लेह्य','अश्वगंधा रसायन लेह्य','Ashvagandhadi Lehya (simplified)','lehya','rasayana_and_strength_support','1) Prepare coarse powder of Ashwagandha root. 2) Boil it gently in water, reduce and filter to obtain decoction. 3) Add sugar/jaggery and ghee in suitable proportions and cook to semisolid lehya consistency. 4) Allow to cool and store in airtight container.','decoction_pot;stirring_spoon;wide_pan;airtight_jar','1–2 hours including decoction and lehya preparation.','Several doses depending on starting quantities; thick semisolid paste.','Store in clean, dry, airtight jar away from heat.','Often 3–6 months under good storage conditions.','{"adult":"5–10 g once or twice daily under professional supervision","child":"use only under specialist pediatric guidance"}','morning_and_or_evening_after_food','lukewarm_milk_or_lukewarm_water_as_suitable','Classical Rasayana-type preparation used for debility and Vata disorders; dosing and duration must be individualized.','2025-12-01 16:57:27',NULL,'ayurveda',71);
INSERT INTO preparations VALUES(15,'Shankhpushpi Decoction','शंखपुष्पी काढ़ा','शंखपुष्पी काढा','Shankhapushpi Kwatha','decoction','memory_and_calm_support','1) Take coarse powder of dried Shankhpushpi whole plant. 2) Add to water (approx. 1:16) and boil gently, reducing to about one-quarter. 3) Filter warm and administer in small doses under guidance.','small_pot;strainer;measuring_cup','20–30 minutes.','60–120 ml per batch depending on starting volume.','Use fresh and warm; keep covered if used within a few hours.','Same-day use recommended.','{"adult":"20–40 ml once or twice daily under professional supervision","child":"only under qualified guidance with lower quantity"}','morning_or_evening','plain_or_with_small_amount_of_honey_when_lukewarm_if_suitable','Used traditionally as Medhya Rasayana for memory and calmness along with diet, sleep and lifestyle measures.','2025-12-01 16:57:27',NULL,'ayurveda',72);
INSERT INTO preparations VALUES(16,'Indian Coleus Root Decoction','भारतीय कोलेयस मूल काढ़ा','भारतीय कोलेयस मुळाचा काढा','Makandi Kwatha (simplified)','decoction','cardio_and_respiratory_support','1) Clean Indian Coleus roots and slice into pieces. 2) Prepare coarse pieces and boil with water as kwatha (1:16 → 1:4). 3) Filter and use in strictly supervised small doses.','pot;strainer;knife;measuring_cup','20–30 minutes.','Approx. 60–100 ml per batch.','Use fresh; do not store long.','Same-day use only.','{"adult":"15–30 ml once or twice daily under strict medical supervision","child":"not generally used; only if specifically prescribed"}','as_directed_by_practitioner','plain_or_with_suitable_vehicle_as_advised','Used in some Ayurvedic contexts for cardiac and respiratory support; must be supervised due to hemodynamic effects.','2025-12-01 16:57:27',NULL,'ayurveda',73);
INSERT INTO preparations VALUES(17,'Shallaki Resin Powder','सलई गुग्गुलु चूर्ण','सलई गुग्गुळ चूर्ण','Shallaki Churna','powder','joint_and_inflammation_support','1) Clean Indian Frankincense (Shallaki) oleo-gum-resin to remove impurities. 2) Shade-dry if needed. 3) Pulverize gently to fine or moderately coarse powder. 4) Store in airtight container.','mortar_and_pestle_or_grinder;airtight_container','30–60 minutes including cleaning and grinding.','Close to dry resin weight.','Store in cool, dry place away from heat and moisture.','Typically a few months under proper storage.','{"adult":"500–1000 mg once or twice daily as per practitioner","child":"only under specialist supervision"}','after_food','lukewarm_water_or_as_directed','Used traditionally as supportive agent in joint and inflammatory conditions; not a replacement for rheumatology care.','2025-12-01 16:57:27',NULL,'ayurveda',74);
INSERT INTO preparations VALUES(18,'Drumstick Leaf Soup','सहजन पत्ता सूप','शेवग्याच्या पानांचे सूप','Shigru Patra Supa (dietary)','medicated_food','nutritive_and_metabolic_support','1) Wash Drumstick leaves thoroughly and remove tough stalks. 2) Boil in water with small amount of moong dal or vegetable stock. 3) Blend lightly if desired and season with mild spices and little ghee/oil. 4) Serve warm as light soup.','cooking_pot;ladle;blender_optional','20–30 minutes.','2–3 servings per batch.','Best consumed fresh.','Same-day use.','{"adult":"one bowl once daily as part of meal if digestion is adequate","child":"small portion according to age"}','with_main_meal','as_part_of_light_diet','Moringa/Drumstick leaves are rich in micronutrients and used in Ayurveda-inspired diets for weakness, anemia and metabolic support.','2025-12-01 16:57:27',NULL,'ayurveda',75);
INSERT INTO preparations VALUES(19,'Pomegranate Rind Decoction','अनार छिलका काढ़ा','डाळिंब साल काढा','Dadima Tvak Kwatha','decoction','gut_and_cardiac_support','1) Dry Pomegranate rind and break into small pieces. 2) Boil with water and reduce to about one-quarter volume. 3) Filter and use warm as astringent supportive decoction.','pot;strainer;measuring_cup','20–30 minutes.','60–100 ml per batch.','Use fresh; keep covered if used within a few hours.','Same-day recommended.','{"adult":"20–40 ml once or twice daily as supportive drink","child":"small quantity only under guidance"}','after_meals','plain_or_with_small_amount_of_rock_sugar_if_suitable','Astringent, gut-supportive decoction used classically in some Atisara/Grahani and cardiac-supportive contexts.','2025-12-01 16:57:27',NULL,'ayurveda',76);
INSERT INTO preparations VALUES(20,'Lemon Digestive Drink','नींबू पाचन पेय','लिंबू पचन पेय','Nimbuka Peya (simplified)','herbal_drink','digestive_support','1) Squeeze fresh Lemon into lukewarm water. 2) Add a pinch of rock salt and roasted cumin powder if suitable. 3) Stir and consume freshly prepared.','cup;spoon;knife','5–10 minutes.','One serving (about 100–150 ml).','Use immediately; do not store.','Use within 1–2 hours maximum.','{"adult":"one small glass before or with meals if tolerated","child":"small quantity only if suitable"}','before_or_with_food','as_is','Used as simple digestive aid; should be modified or avoided in individuals with severe hyperacidity or ulcers.','2025-12-01 16:57:27',NULL,'ayurveda',77);
INSERT INTO preparations VALUES(21,'Holy Fig Bark Decoction','पीपल की छाल का काढ़ा','पिंपळ सालीचा काढा','Ashvattha Tvak Kwatha','decoction','respiratory_and_cardiac_support','1) Take clean dried bark of Holy Fig and make coarse pieces. 2) Boil with water and reduce as per kwatha method. 3) Filter and use warm in supervised doses.','decoction_pot;strainer;measuring_cup','20–30 minutes.','Single or two small servings (60–120 ml).','Use fresh; discard leftover after a few hours.','Same-day use.','{"adult":"20–40 ml once or twice daily as advised","child":"only under professional supervision"}','after_meals_or_as_directed','plain','Referenced in Ayurvedic context for respiratory and cardiac support; do not substitute for modern cardiology treatment.','2025-12-01 16:57:27',NULL,'ayurveda',78);
INSERT INTO preparations VALUES(22,'Banyan Bark Decoction','वट वृक्ष की छाल का काढ़ा','वड सालीचा काढा','Vatavriksha Kwatha','decoction','astringent_and_metabolic_support','1) Collect appropriate Banyan bark sustainably and dry well. 2) Prepare coarse chips and boil in water till reduced. 3) Filter and use only under practitioner supervision.','pot;strainer;knife;measuring_cup','20–30 minutes.','60–120 ml per batch.','Use freshly prepared.','Same-day use; do not store long.','{"adult":"15–30 ml once or twice daily only under practitioner supervision","child":"generally not used without expert advice"}','as_directed','plain','Used in some traditional contexts in metabolic and shotha-related conditions; sustainability and proper identification are important.','2025-12-01 16:57:27',NULL,'ayurveda',79);
INSERT INTO preparations VALUES(23,'Coconut Milk Tonic','नारियल दूध टॉनिक','नारळाचे दूध टॉनिक','Narikela Ksheerapaka (simplified)','nutritive_drink','balya_and_cooling_support','1) Grate fresh Coconut kernel. 2) Blend with warm water and strain to obtain Coconut milk. 3) Warm gently if needed and consume fresh; sweeten lightly if suitable.','grater;blender;strainer;cup','15–20 minutes.','One or two servings (100–150 ml each).','Use fresh; avoid long storage.','Use within a few hours; refrigeration only for very short time.','{"adult":"one small cup once or twice daily according to digestion","child":"small quantity according to age"}','with_or_after_food','as_is','Cooling, nutritive drink often used in Pitta conditions and general weakness; consider Kapha/Medo status and digestion.','2025-12-01 16:57:27',NULL,'ayurveda',80);
INSERT INTO preparations VALUES(24,'Nutmeg Sleep Milk','जायफल निद्रा दूध','जायफळ निद्रा दूध','Jatiphala Ksheera (simplified)','medicated_milk','sleep_and_digestive_support','1) Take a very small pinch of freshly grated Nutmeg. 2) Boil milk, then add Nutmeg at the end and simmer briefly. 3) Cool to comfortable warm temperature and drink before bed.','small_grater;pan;cup','10–15 minutes.','One cup (about 100–150 ml).','Use immediately; do not store.','Single use at a time.','{"adult":"one small cup at bedtime with a very small pinch of Nutmeg under guidance","child":"use only under expert supervision"}','bedtime','as_is','Traditional home-style support for sleep and digestion; Nutmeg must be used in very small doses due to toxicity risk at higher intake.','2025-12-01 16:57:27',NULL,'ayurveda',81);
INSERT INTO preparations VALUES(25,'Saffron Milk','केसर दूध','केशर दूध','Kumkuma Ksheera','medicated_milk','rasayana_and_mood_support','1) Soak a few strands of Saffron in warm milk for several minutes. 2) Optionally heat gently again and stir. 3) Consume warm in small quantity.','cup;spoon;small_pan','10–15 minutes including soaking.','One small cup (about 100–150 ml).','Use fresh.','Single serving; do not store.','{"adult":"one small cup once daily or a few times a week as advised","child":"very small amount only if suitable and advised"}','evening_or_as_directed','as_is','Classical Rasayana-style milk used in small amounts for mind, heart and complexion support; potent and costly, so doses are small.','2025-12-01 16:57:27',NULL,'ayurveda',82);
INSERT INTO preparations VALUES(26,'Black Cardamom Digestive Decoction','बड़ी इलायची काढ़ा','मोठी वेलची काढा','Brihad Ela Kwatha (simplified)','decoction','digestive_and_respiratory_support','1) Crush Black Cardamom fruits lightly. 2) Boil in water for several minutes to extract aroma. 3) Filter and sip warm after meals.','small_pot;crusher;strainer','10–15 minutes.','One or two small cups (30–60 ml each).','Use fresh and warm.','Same-day only.','{"adult":"15–30 ml once or twice daily after food","child":"few teaspoons diluted, only if suitable"}','after_meals','as_is','Traditional warming aromatic decoction supportive in digestion and mild respiratory discomfort.','2025-12-01 16:57:27',NULL,'ayurveda',83);
INSERT INTO preparations VALUES(27,'Star Anise Digestive Infusion','चक्र फूल पाचन फांटा','चक्रफूल पचन फांटा','Chakra Phala Phanta','herbal_tea','digestive_support','1) Lightly crush one Star Anise. 2) Pour hot water over and cover for 5–10 minutes. 3) Strain and sip warm after meals.','cup_or_teapot;strainer','10–15 minutes.','One cup (100–150 ml).','Use immediately.','Single use.','{"adult":"one cup after heavy meal if suitable","child":"small quantity only under guidance"}','after_meals','as_is','Mild aromatic infusion for post-meal heaviness and gas in some individuals.','2025-12-01 16:57:27',NULL,'ayurveda',84);
INSERT INTO preparations VALUES(28,'Raisin Decoction','किशमिश काढ़ा','किशमिश काढा','Draksha Kashaya (simplified)','decoction','cooling_and_lung_support_mild','1) Soak clean Raisins (dried Grapes) briefly and then boil in water. 2) Simmer until water is mildly sweet and reduced. 3) Filter and consume lukewarm.','small_pot;strainer;measuring_cup','20–25 minutes.','60–120 ml per batch.','Use fresh.','Same-day only.','{"adult":"20–40 ml once or twice daily as supportive drink","child":"small quantity depending on age"}','between_meals_or_as_directed','as_is','Raisin-based decoction (Draksha) is used traditionally for mild cough, burning and debility; sugar load must be considered in diabetes.','2025-12-01 16:57:27',NULL,'ayurveda',85);
INSERT INTO preparations VALUES(29,'Dates Energy Drink','खजूर ऊर्जा पेय','खजूर ऊर्जा पेय','Khajura Ksheerapaka (simplified)','nutritive_drink','balya_and_energy_support','1) Soak deseeded Dates in warm water or milk for some time. 2) Blend or mash to smooth drink. 3) Consume fresh as energy-supportive drink.','soaking_bowl;blender_or_masher;cup','20–30 minutes including soaking.','One or two servings (100–150 ml).','Use immediately; refrigeration only for very short time.','Same-day use.','{"adult":"one small glass once a day as per caloric needs","child":"small quantity adjusted to age"}','morning_or_as_directed','as_is','Nourishing sweet drink commonly used for weakness; must be used carefully in diabetes or obesity.','2025-12-01 16:57:27',NULL,'ayurveda',86);
INSERT INTO preparations VALUES(30,'Black Cumin Seed Powder','कलौंजी बीज चूर्ण','काळे जिरे बी चूर्ण','Krishna Jiraka Churna (simplified)','powder','digestive_and_metabolic_support','1) Clean and lightly dry-roast Black Cumin seeds. 2) Grind to fine powder. 3) Store in airtight container; use in small pinches along with food.','pan;grinder;airtight_container','15–20 minutes.','Close to dry seed weight.','Store in cool, dry place.','Typically 2–3 months for best aroma.','{"adult":"1–2 g daily divided with food or as advised","child":"tiny pinch only, if at all, under guidance"}','with_food','sprinkled_on_food_or_with_lukewarm_water','Used as spice-based support in digestion and metabolism; may interact with metabolic medications in some individuals.','2025-12-01 16:57:27',NULL,'ayurveda',87);
INSERT INTO preparations VALUES(31,'Garden Cress Seed Milk','हलिम बीज दूध','हालिम बीज दूध','Chandrashura Ksheerapaka (popular form)','medicated_milk','bone_and_iron_support','1) Soak Garden Cress seeds briefly in water. 2) Add to milk and boil gently until seeds swell. 3) Sweeten mildly if suitable and consume warm.','small_pot;spoon;cup','15–20 minutes.','One cup per preparation.','Use fresh; do not store.','Single serving.','{"adult":"one cup a few times per week as guided","child":"small quantity adjusted for age"}','evening_or_as_directed','as_is','Known home-style preparation for iron and bone support; may aggravate Pitta or cause gastric discomfort in some individuals.','2025-12-01 16:57:27',NULL,'ayurveda',88);
INSERT INTO preparations VALUES(32,'Khadira Skin Wash Decoction','खैर त्वचा धुलाई काढ़ा','खैर त्वचा धुण्याचा काढा','Khadira Kwatha (external)','decoction','skin_support_external','1) Boil Khadira heartwood pieces in water until volume reduces and color deepens. 2) Cool to lukewarm and use externally as wash for affected skin areas as advised.','pot;strainer;bowl','20–30 minutes.','Sufficient for one or two external washes.','Use same day; discard leftover.','Same-day external use.','{"adult":"external use only, as per practitioner","child":"external use only, under supervision"}','external_use_only','none','Khadira decoction is traditionally used as external wash in chronic skin conditions along with internal management.','2025-12-01 16:57:27',NULL,'ayurveda',89);
INSERT INTO preparations VALUES(33,'Vetiver Cooling Infusion','खस ठंडा पेय','खस थंड पेय','Ushira Jala / Ushira Phanta','herbal_water','cooling_and_pitta_support','1) Wash Vetiver roots thoroughly to remove soil. 2) Tie a small bundle and immerse in pot of drinking water, or infuse in warm water for 1–2 hours. 3) Remove bundle and consume infused water cool or at room temperature.','pot_or_water_matka;clean_cloth_for_bundle','1–2 hours infusion; active work is a few minutes.','Several glasses depending on water volume.','Can be used through the day if kept covered and clean.','Same-day use recommended.','{"adult":"small glass 2–3 times daily in hot season if suitable","child":"smaller amounts as per thirst and suitability"}','throughout_hot_season_as_needed','as_is','Ushira (Vetiver) infused water is a classical cooling drink for Pitta and heat conditions; hygiene and source quality of roots are important.','2025-12-01 16:57:27',NULL,'ayurveda',90);
INSERT INTO preparations VALUES(34,'Brahmi Memory Decoction','ब्राह्मी स्मरण शक्ति काढ़ा','ब्राह्मी स्मरणशक्ती काढा','Brahmi Kwatha (Medhya Rasayana)','decoction','memory_and_calm_support','1) Take coarse powder or small pieces of Brahmi whole plant. 2) Add to water (approx. 1 part herb : 16 parts water). 3) Boil gently and reduce to about one-quarter volume. 4) Filter while warm and use in small, supervised doses.','decoction_pot;strainer;measuring_cup','20–30 minutes.','Approximately 60–120 ml per batch.','Use fresh and warm; do not store for long. Keep covered if using within a few hours.','Same-day use recommended for best quality.','{"adult":"20–40 ml once or twice daily under professional supervision","child":"lower quantity only under qualified guidance"}','morning_or_evening','plain_or_with_small_amount_of_honey_when_lukewarm_if_suitable','Brahmi decoction is traditionally used as Medhya (brain-supportive) Rasayana along with proper sleep, diet and lifestyle; not a replacement for neurological care.','2025-12-01 17:26:15',NULL,'ayurveda',1);
INSERT INTO preparations VALUES(35,'Gotu Kola Leaf Decoction','मंडूकपर्णी पत्ती काढ़ा','मांडूकपर्णी पानांचा काढा','Mandukaparni Kwatha (simplified)','decoction','memory_and_skin_support','1) Wash fresh Gotu Kola leaves thoroughly. 2) Coarsely chop and add to water. 3) Boil gently and reduce, then filter. 4) Use in small quantities as directed.','pot;knife;strainer','15–20 minutes.','60–100 ml per batch.','Use freshly prepared; do not keep overnight.','Same-day use.','{"adult":"15–30 ml once or twice daily under guidance","child":"only under expert supervision"}','morning_or_evening','plain','Gotu Kola is used in Ayurveda for Medhya and skin support; dose and duration are individualized by practitioner.','2025-12-01 17:26:15',NULL,'ayurveda',2);
INSERT INTO preparations VALUES(36,'Giloy Stem Decoction','गिलोय का काढ़ा','गुळवेलचा काढा','Guduchi Kwatha','decoction','immune_and_fever_support','1) Cut fresh or dried Giloy stems into small pieces. 2) Prepare coarse powder if needed. 3) Boil in water (1:16 → 1:4) to make decoction. 4) Filter and use warm under supervision.','decoction_pot;knife;strainer','20–30 minutes.','60–120 ml per batch.','Use fresh, preferably within a few hours.','Same-day only.','{"adult":"20–40 ml once or twice daily depending on condition and advice","child":"only under pediatric Ayurvedic supervision"}','morning_and/or_evening','plain_or_with_small_amount_of_honey_when_lukewarm_if_suitable','Guduchi kwatha is classical Rasayana and Jwara-supportive decoction; monitoring is needed in chronic conditions.','2025-12-01 17:26:15',NULL,'ayurveda',3);
INSERT INTO preparations VALUES(37,'Neem Leaf Decoction','नीम पत्ती काढ़ा','कडुनिंब पानांचा काढा','Nimba Patra Kwatha','decoction','skin_and_metabolic_support','1) Wash fresh Neem leaves thoroughly. 2) Boil a small quantity in water till color deepens and volume reduces moderately. 3) Filter. 4) Use externally as wash for skin or in very small oral doses only under professional supervision.','pot;strainer','15–20 minutes.','Approx. 100–150 ml.','Use fresh; discard leftover after a few hours.','Same-day use.','{"adult":"external wash as needed; oral use typically 10–20 ml in select indications under expert care","child":"external use only unless strictly prescribed"}','external_or_as_directed','plain','Neem decoction is a strong, bitter preparation used classically for skin, Pitta and Kapha conditions; internal use must be supervised.','2025-12-01 17:26:15',NULL,'ayurveda',4);
INSERT INTO preparations VALUES(38,'Arjuna Bark Decoction','अर्जुन की छाल का काढ़ा','अर्जुन सालीचा काढा','Arjuna Kwatha','decoction','cardiac_support','1) Use properly cleaned, dried Arjuna bark. 2) Prepare coarse pieces and boil in water (kwatha method) until reduced. 3) Filter and use warm.','decoction_pot;strainer;knife','20–30 minutes.','60–100 ml per batch.','Use fresh.','Same-day only.','{"adult":"20–40 ml once or twice daily under cardiology and Ayurvedic guidance","child":"only if specifically indicated by pediatric specialist"}','morning_and/or_evening','typically_with_lukewarm_water_or_milk_as_advised','Arjuna decoction is classical supportive preparation for Hridroga; not a substitute for modern cardiac interventions.','2025-12-01 17:26:15',NULL,'ayurveda',5);
INSERT INTO preparations VALUES(39,'Gokshura Seed Decoction','गोक्षुरु बीज काढ़ा','गोक्षुर बी काढा','Gokshuradi Kwatha (simplified single-herb)','decoction','urinary_and_reproductive_support','1) Take cleaned, crushed Gokshura fruits/seeds. 2) Boil with water and reduce to kwatha volume. 3) Filter and use in small quantities under guidance.','pot;crusher;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"20–40 ml once or twice daily under supervision","child":"only under pediatric Ayurvedic guidance"}','morning_and/or_evening','plain','Traditionally used in urinary and reproductive support; hydration and medical evaluation remain essential.','2025-12-01 17:26:15',NULL,'ayurveda',6);
INSERT INTO preparations VALUES(40,'Punarnava Root Decoction','पुनर्नवा मूल काढ़ा','पुनर्नवा मुळाचा काढा','Punarnava Kwatha','decoction','renal_and_edema_support','1) Clean and dry Punarnava roots, cut into small pieces. 2) Boil with water and reduce as per kwatha rule. 3) Filter and drink warm in small supervised doses.','decoction_pot;knife;strainer','20–30 minutes.','60–100 ml per batch.','Use fresh.','Same-day use.','{"adult":"20–40 ml once or twice daily, duration individualized","child":"only under qualified supervision"}','morning_or_evening','plain','Punarnava kwatha is classical Mutravaha and Shotha-supportive; monitoring kidney function and electrolytes via modern medicine is important.','2025-12-01 17:26:15',NULL,'ayurveda',7);
INSERT INTO preparations VALUES(41,'Shatavari Medicated Milk','शतावरी क्षीरपाक','शतावरी क्षीरपाक','Shatavari Ksheerapaka','medicated_milk','female_health_and_rasayana_support','1) Prepare coarse powder of dried Shatavari roots. 2) Boil with water and milk together in recommended proportion, stirring to avoid sticking. 3) Reduce to ksheerapaka consistency and filter if needed. 4) Serve warm.','pan;stirrer;strainer','20–30 minutes.','One or two servings per batch.','Use fresh and warm.','Same-day.','{"adult":"50–100 ml once or twice daily as advised","child":"use only if prescribed by pediatric or gynecological expert"}','morning_and/or_evening','as_is','Classically used as Rasayana, especially in women’s health and Pitta/Vata conditions; lactose intolerance and digestive capacity must be considered.','2025-12-01 17:26:15',NULL,'ayurveda',8);
INSERT INTO preparations VALUES(42,'Licorice Gastric Support Decoction','यष्टिमधु जठर काढ़ा','जेष्ठमध जठर काढा','Yashtimadhu Kwatha','decoction','ulcer_and_throat_support','1) Cut Licorice roots into small pieces. 2) Boil gently in water for 10–15 minutes and reduce slightly. 3) Filter and sip warm.','pot;strainer;knife','15–20 minutes.','60–100 ml.','Use fresh; avoid long storage.','Same-day use.','{"adult":"20–40 ml once or twice daily for short periods under guidance","child":"smaller quantities only if advised"}','after_food_or_as_directed','as_is','Yashtimadhu is classical for throat and gastric comfort; care is needed in hypertension, edema or heart failure due to potential salt/water retention.','2025-12-01 17:26:15',NULL,'ayurveda',9);
INSERT INTO preparations VALUES(43,'Kalmegh Bitter Decoction','कालमेघ कड़वा काढ़ा','कालमेघ कडू काढा','Bhuneemadi Kwatha (single-herb style)','decoction','liver_and_fever_support','1) Prepare coarse powder of Kalmegh herb. 2) Boil with water and reduce to kwatha volume. 3) Filter and drink in very small doses due to strong bitterness.','decoction_pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily in short courses under supervision","child":"only under strict pediatric guidance"}','after_food','plain','Kalmegh is strongly bitter and used in Ayurveda in yakrit (liver), jwara and Agni-related contexts; excessive use is avoided.','2025-12-01 17:26:15',NULL,'ayurveda',10);
INSERT INTO preparations VALUES(44,'Bael Pulp Digestive Drink','बेल गूदा पाचन पेय','बेल फळ गर पचन पेय','Bilva Phala Sharbat (non-fermented)','medicated_food','diarrhea_and_digestive_support','1) Break ripe Bael fruit and scoop out pulp. 2) Soak in water and mash to remove fibers and seeds. 3) Strain and, if suitable, add small amount of rock sugar. 4) Serve fresh.','knife;bowl;masher;strainer','20–30 minutes.','2–3 glasses depending on fruit size.','Best consumed fresh; short refrigeration only if needed.','Same-day use.','{"adult":"one glass once or twice daily in diarrhea/IBS patterns as per advice","child":"smaller quantity adjusted to age"}','after_food_or_between_meals','as_is','Bilva pulp drink is classical for Atisara/Grahani support; dehydration or dysentery still require immediate modern care.','2025-12-01 17:26:15',NULL,'ayurveda',11);
INSERT INTO preparations VALUES(45,'Guggul Resin Paste Base','गुग्गुलु राल आधार','गुग्गुळ राळ बेस','Guggulu Kalka (simplified)','resin_paste','joint_and_lipid_support_base','1) Purify crude Guggul resin by classical shodhana (not detailed here). 2) Once purified and dried, soften slightly in a water bath and triturate with small amount of suitable liquid (like decoction or ghee) to paste. 3) Use as base to prepare different Guggulu yogas.','water_bath;spatula;mortar_and_pestle','Several hours including purification; paste-making 30–40 minutes.','Variable; small jar of paste.','Store in airtight container in cool, dry place.','Shelf life depends on full formulation; base paste generally used within few months in pharmacy.','{"adult":"dose depends on specific Guggulu formulation, typically 250–1000 mg per dose","child":"only under expert supervision"}','as_directed','usually_with_warm_water_or_decoction','Guggul is powerful resin used in many classical formulas for joints, lipids and shotha; shodhana and correct dosing are mandatory.','2025-12-01 17:26:15',NULL,'ayurveda',12);
INSERT INTO preparations VALUES(46,'Bhumyamalaki Liver Decoction','भूम्यामलकी यकृत काढ़ा','भूयामलकी यकृत काढा','Bhumyamalaki Kwatha','decoction','liver_and_jaundice_support','1) Take whole plant of dried Bhumyamalaki as coarse powder. 2) Boil in water and reduce as per kwatha method. 3) Filter and use in small doses.','pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily in short to medium courses under supervision","child":"pediatric dose only by specialist"}','morning_and/or_evening','plain','Bhumyamalaki is classical in yakrit and kamala contexts; liver function monitoring and integration with hepatology care are important.','2025-12-01 17:26:15',NULL,'ayurveda',13);
INSERT INTO preparations VALUES(47,'Kutki Bitter Decoction','कुटकी कड़वा काढ़ा','कुटकी कडू काढा','Katuki Kwatha','decoction','liver_and_fever_support','1) Use dried rhizomes of Kutki, broken into coarse pieces. 2) Boil with water and reduce well due to high bitterness. 3) Filter and use strictly under supervision.','decoction_pot;strainer','20–30 minutes.','60–80 ml.','Use fresh.','Same-day.','{"adult":"10–20 ml once or twice daily due to potency","child":"not usually used without specialist guidance"}','after_food_or_as_directed','plain','Kutki is very potent Tikta, used in severe Pitta-yakrit-jwara contexts; dosage is small and monitored.','2025-12-01 17:26:15',NULL,'ayurveda',14);
INSERT INTO preparations VALUES(48,'Pippali Churna','पिप्पली चूर्ण','पिप्पळी चूर्ण','Pippali Churna','powder','respiratory_and_dipana_support','1) Clean dried Long Pepper fruits. 2) Powder to fine churna and sieve if needed. 3) Store in airtight container.','grinder;sieve;airtight_jar','20–30 minutes.','Close to dry fruit weight.','Store in cool, dry place away from moisture.','2–3 months for aroma and potency.','{"adult":"500–1000 mg once or twice daily as advised","child":"very small pinch only if suitable"}','after_food_or_with_medicinal_formulations','with_honey_or_ghee_or_as_directed','Pippali is important in Rasayana and Deepana-Pachana; excessive heat or gastric irritation should be monitored.','2025-12-01 17:26:15',NULL,'ayurveda',15);
INSERT INTO preparations VALUES(49,'Black Pepper Digestive Powder','काली मिर्च पाचन चूर्ण','काळी मिरी पचन चूर्ण','Maricha Yoga (Trikatu-style single emphasis)','powder','digestive_and_respiratory_support','1) Lightly dry-roast Black Pepper and allow to cool. 2) Grind to fine powder. 3) Optionally combine with small amounts of ginger and long pepper powders. 4) Store airtight.','pan;grinder;airtight_container','15–20 minutes.','Close to total spice weight.','Store in cool, dry place.','1–2 months optimum.','{"adult":"250–500 mg once or twice daily with food","child":"tiny pinch only if suitable"}','with_meals','with_ghee_or_honey_or_as_sprinkle_on_food','Used as Deepana–Pachana support; high Pitta, ulcers or bleeding conditions need caution.','2025-12-01 17:26:15',NULL,'ayurveda',16);
INSERT INTO preparations VALUES(50,'Vidanga Krimi Churna','विदंग कृमि चूर्ण','विदंग कृमि चूर्ण','Vidanga Churna','powder','anthelmintic_support','1) Clean and dry Vidanga fruits. 2) Powder to fine churna. 3) Store in cool, dry, airtight container. 4) Use in small doses only under supervision.','grinder;sieve;airtight_jar','20–30 minutes.','Close to dry fruit weight.','Store airtight away from moisture.','Few months if stored well.','{"adult":"1–3 g once or twice daily for short periods under medical guidance","child":"only under pediatric guidance"}','before_food','with_honey_or_lukewarm_water','Vidanga is classical krimighna herb; improper use can irritate gut; stool evaluation and deworming protocols must follow medical advice.','2025-12-01 17:26:15',NULL,'ayurveda',17);
INSERT INTO preparations VALUES(51,'Chitrak Root Decoction','चित्रक मूल काढ़ा','चित्रक मुळाचा काढा','Chitraka Kwatha','decoction','agni_and_metabolic_support','1) Use dried Chitrak roots cut into small pieces. 2) Prepare kwatha by boiling with water and reducing. 3) Filter and use in very small quantity due to strong heating nature.','pot;strainer;knife','20–25 minutes.','60–80 ml.','Use fresh.','Same-day.','{"adult":"10–20 ml once or twice daily as per strict supervision","child":"generally avoided"}','before_food_or_as_directed','with_suitable_anupana_like_ghee_or_buttermilk_as_advised','Chitrak is very Tikshna and Ushna; misuse can cause gastritis or bleeding; always supervised.','2025-12-01 17:26:15',NULL,'ayurveda',18);
INSERT INTO preparations VALUES(52,'Jatamansi Calm Powder','जटामांसी शांत चूर्ण','जटामांसी शांत चूर्ण','Jatamansi Churna','powder','anxiety_and_sleep_support','1) Clean dried Jatamansi rhizomes. 2) Powder to fine churna. 3) Store airtight. 4) Use in small, supervised doses.','grinder;sieve;airtight_container','20–30 minutes.','Close to dry rhizome weight.','Store cool and dry.','Few months if well stored.','{"adult":"500–1000 mg once or twice daily as directed","child":"only under specialist guidance"}','evening_or_bedtime','with_lukewarm_water_or_milk','Jatamansi is Medhya and manas-balancing herb used in anxiety and sleep-related contexts; may have additive effect with sedatives.','2025-12-01 17:26:15',NULL,'ayurveda',19);
INSERT INTO preparations VALUES(53,'Kustha External Paste','कुष्ठ बाह्य लेप','कुष्ठ बाह्य लेप','Kustha Lepa','paste','skin_support_external','1) Use powdered Kustha root. 2) Mix with suitable liquid (water, decoction, or oil) to form smooth paste. 3) Apply thinly on indicated skin areas as per advice and wash after recommended time.','bowl;spoon;applicator','10–15 minutes to prepare; application time additional.','Sufficient for one or two applications.','Prepare fresh each time.','Same-day external use.','{"adult":"external application only, as per physician","child":"external use cautiously under supervision"}','external_use_only','none','Kustha is a strong herb for Kustha roga (skin disorders) in classical texts; external use is adjunct to internal and modern therapy.','2025-12-01 17:26:15',NULL,'ayurveda',20);
INSERT INTO preparations VALUES(54,'Vasa Leaf Decoction','वासा पत्ती काढ़ा','वसा पानांचा काढा','Vasa Kwatha','decoction','cough_and_hemoptysis_support','1) Take clean dried Malabar Nut (Vasa) leaves. 2) Boil with water and reduce as per kwatha rule. 3) Filter and take in small supervised doses.','decoction_pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily under practitioner guidance","child":"only under pediatric supervision"}','after_food_or_as_directed','plain','Vasa is classical for cough and certain bleeding disorders; self-medication in hemoptysis is unsafe and needs pulmonology input.','2025-12-01 17:26:15',NULL,'ayurveda',21);
INSERT INTO preparations VALUES(55,'Saptaparna Bark Decoction','सप्तपर्ण की छाल का काढ़ा','सप्तपर्ण सालीचा काढा','Saptaparna Kwatha','decoction','fever_and_parasitic_support','1) Use dried bark of Saptaparna cut into small pieces. 2) Boil with water and reduce to kwatha. 3) Filter and take in small doses, typically in specific fever or krimi contexts.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily only under specialist supervision","child":"not routinely used"}','as_directed','plain','Saptaparna is a potent herb used in certain fevers and parasitic patterns; always used in properly balanced formulations in practice.','2025-12-01 17:26:15',NULL,'ayurveda',22);
INSERT INTO preparations VALUES(56,'Mustaka Digestive Churna','मुस्ता पाचन चूर्ण','मुस्ता पचन चूर्ण','Mustaka Churna','powder','diarrhea_and_digestive_support','1) Clean and dry rhizomes of Mustaka. 2) Powder to fine churna and sieve. 3) Store in airtight container.','grinder;sieve;airtight_jar','20–30 minutes.','Close to rhizome weight.','Store cool and dry.','Few months.','{"adult":"1–3 g once or twice daily under guidance","child":"lower dose only if prescribed"}','after_food_or_between_meals','with_buttermilk_or_lukewarm_water','Traditional in Atisara/Grahani and digestive issues; hydration, diet and stool tests remain important.','2025-12-01 17:26:15',NULL,'ayurveda',23);
INSERT INTO preparations VALUES(57,'Atibala Root Decoction','अतिबला मूल काढ़ा','अतिबला मुळाचा काढा','Atibala Kwatha','decoction','vata_and_strength_support','1) Take dried roots (and optionally leaves) of Atibala. 2) Make coarse pieces and boil with water to kwatha volume. 3) Filter and drink warm.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"20–40 ml once or twice daily under guidance","child":"only under pediatric supervision"}','morning_and/or_evening','as_directed','Atibala is used similarly to Bala in certain Vata and debility contexts; species identity and dose are important.','2025-12-01 17:26:15',NULL,'ayurveda',24);
INSERT INTO preparations VALUES(58,'Bala Root Decoction','बला मूल काढ़ा','बला मुळाचा काढा','Bala Kwatha','decoction','vata_and_strength_support','1) Take cleaned dried Bala roots. 2) Prepare coarse cut and boil in water as kwatha. 3) Filter and use warm.','pot;strainer;knife','20–30 minutes.','60–100 ml per batch.','Use fresh.','Same-day use only.','{"adult":"20–40 ml once or twice daily under supervision","child":"only under expert pediatric guidance"}','morning_and/or_evening','as_directed','Bala is valued for Vata, nerve and strength support; also used in taila/ghrita; caution in hypertension depending on formulation.','2025-12-01 17:26:15',NULL,'ayurveda',25);
INSERT INTO preparations VALUES(59,'Kantakari Cough Decoction','कंटकारी खांसी काढ़ा','कंटकारी खोकला काढा','Kantakari Kwatha','decoction','respiratory_support','1) Take dried Kantakari whole plant (especially aerial parts) as coarse powder. 2) Boil in water and reduce to approx. one-quarter. 3) Filter and serve warm in small supervised doses.','decoction_pot;strainer;measuring_cup','20–30 minutes.','60–100 ml per batch.','Use fresh and warm; discard leftover.','Same-day use only.','{"adult":"15–30 ml once or twice daily under supervision","child":"only under pediatric Ayurvedic guidance"}','after_food_or_as_directed','plain','Kantakari is part of Dasamoola and used for cough/asthma patterns; classically combined with other herbs.','2025-12-01 17:38:56',NULL,'ayurveda',26);
INSERT INTO preparations VALUES(60,'Brihati Cough Decoction','बृहतखीरा खांसी काढ़ा','भुई वांगे खोकला काढा','Brihati Kwatha','decoction','respiratory_support','1) Take dried Brihati whole plant (without large thorns). 2) Boil with water and reduce as per kwatha rule. 3) Filter and give warm.','pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily with supervision","child":"only if prescribed"}','after_food','plain','Brihati is also a Dasamoola member, used in cough/asthma; usually combined with other roots.','2025-12-01 17:38:56',NULL,'ayurveda',27);
INSERT INTO preparations VALUES(61,'Asthisamharaka Bone Decoction','अस्थिसंहरक अस्थि काढ़ा','अस्थिसंहरक हाड काढा','Asthisamharaka Kwatha','decoction','bone_and_fracture_support','1) Use dried stem pieces of Asthisamharaka (Cissus quadrangularis). 2) Boil with water until reduced. 3) Filter and use warm in small supervised doses.','decoction_pot;strainer;knife','20–30 minutes.','60–100 ml per batch.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily along with orthopedic care","child":"only under pediatric supervision"}','after_meals','plain','Used traditionally as adjunct for fractures and bone weakness; not a substitute for proper immobilization and orthopedic management.','2025-12-01 17:38:56',NULL,'ayurveda',28);
INSERT INTO preparations VALUES(62,'Vijayasar Wood Decoction','विजयसार लकड़ी काढ़ा','विजयसार लाकूड काढा','Vijaysar Kwatha','decoction','diabetes_support','1) Take heartwood chips of Vijayasar. 2) Soak briefly then boil in water until reduced and colored. 3) Filter and drink in supervised doses.','pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"20–40 ml once or twice daily along with diabetic management","child":"use only if prescribed"}','before_food_or_as_directed','plain','Popular adjunct in type 2 diabetes; glucose monitoring and modern therapy remain primary.','2025-12-01 17:38:56',NULL,'ayurveda',29);
INSERT INTO preparations VALUES(63,'Manjishta Blood Decoction','मंजिष्ठा रक्त शोधक काढ़ा','मंजिष्ठा रक्तशोधक काढा','Manjishta Kwatha','decoction','blood_and_skin_support','1) Use dried Manjishta roots cut into small pieces. 2) Boil with water and reduce as per kwatha. 3) Filter and use.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"20–40 ml once or twice daily as advised","child":"only under specialist guidance"}','after_food','plain','Classical herb for Rakta and skin support; liver and kidney status must be considered.','2025-12-01 17:38:56',NULL,'ayurveda',30);
INSERT INTO preparations VALUES(64,'Golden Shower Flower Infusion','अमलतास पुष्प फांटा','बहावा फुलांचा फांटा','Aragvadha Pushpa Phanta','herbal_tea','mild_laxative_support','1) Use dried flowers of Golden Shower Tree. 2) Pour hot water over a small quantity and cover for 5–10 minutes. 3) Strain and use in small doses.','cup;strainer','10–15 minutes.','One cup per preparation.','Use fresh.','Same-day.','{"adult":"20–40 ml as mild laxative support when advised","child":"only under pediatric supervision"}','bedtime_or_as_directed','as_is','Golden Shower Tree is used for mild laxative and skin support; pods are stronger and used cautiously.','2025-12-01 17:38:56',NULL,'ayurveda',31);
INSERT INTO preparations VALUES(65,'Kutaja Bark Decoction','कुटज की छाल का काढ़ा','कुडज सालीचा काढा','Kutaja Kwatha','decoction','antidiarrheal_support','1) Take dried Kutaja bark. 2) Prepare coarse pieces and boil in water to reduce. 3) Filter and use in small doses.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"20–40 ml once or twice daily in diarrhea/IBS pattern as advised","child":"only under pediatric care"}','as_directed','plain','Kutaja is classical antidiarrheal herb; dehydration and infection still require modern medical care.','2025-12-01 17:38:56',NULL,'ayurveda',32);
INSERT INTO preparations VALUES(66,'Kokilaksha Decoction','कौकिलाक्ष काढ़ा','कोकिलाक्ष काढा','Kokilaksha Kwatha','decoction','urinary_and_joint_support','1) Use dried aerial parts of Kokilaksha as coarse powder. 2) Boil with water and reduce. 3) Filter and administer warm.','pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily under guidance","child":"use only if prescribed"}','after_food','plain','Used in classical texts for urinary and joint disorders; kidney function and uric acid should be monitored.','2025-12-01 17:38:56',NULL,'ayurveda',33);
INSERT INTO preparations VALUES(67,'Noni Fruit Tonic','नोनी फल टॉनिक','नोनी फळ टॉनिक','Noni Phala Ras (folk)','juice','immune_and_vitality_support','1) Take fully ripe Noni fruits. 2) Wash, slice and press to extract juice, or ferment-controlled juice as per pharmacopeia. 3) Dilute with water before intake.','knife;press_or_juicer;strainer','20–30 minutes (non-fermented).','Several small servings.','Refrigerate and use within a few days if fresh; fermented products follow label.','Few days (fresh juice).','{"adult":"10–30 ml diluted once or twice daily as guided","child":"small amount only if suitable"}','morning_or_as_directed','diluted_with_water','Noni has become popular nutraceutical; quality control and dose individualization are important.','2025-12-01 17:38:56',NULL,'ayurveda',34);
INSERT INTO preparations VALUES(68,'Apamarga Kshara Base','अपामार्ग क्षार आधार','अपामार्ग क्षार बेस','Apamarga Kshara (simplified)','alkaline_salt','digestive_and_fistula_support','1) Burn dried whole plant of Apamarga to ash as per classical kshara method. 2) Extract water-soluble portion, filter and evaporate to obtain kshara. 3) Dry and store airtight.','earthen_pan;filter_cloth;evaporation_pan','Several hours including burning and evaporation.','Depends on starting biomass.','Store in airtight container protected from moisture.','Many months if dry and airtight.','{"adult":"dose in tens to few hundred milligrams as part of formulations under strict supervision","child":"not generally used"}','as_directed','with_suitable_vehicle_like_buttermilk_or_water','Apamarga kshara is potent and used in ksharasutra and digestive disorders; must be prepared and dosed only by experts.','2025-12-01 17:38:56',NULL,'ayurveda',35);
INSERT INTO preparations VALUES(69,'Red Sandalwood Cooling Decoction','रक्तचंदन शीत काढ़ा','रक्तचंदन थंड काढा','Raktachandana Kwatha','decoction','cooling_and_rakta_support','1) Use chips or coarse powder of Red Sandalwood. 2) Boil in water until color and extract develop. 3) Filter and use in small quantities.','pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily as supportive drink","child":"small quantity only if suitable"}','between_meals_or_as_directed','as_is','Used classically for Pitta-Rakta conditions such as burning, rashes, and epistaxis; internal use should be supervised.','2025-12-01 17:38:56',NULL,'ayurveda',36);
INSERT INTO preparations VALUES(70,'Patha Digestive Decoction','पाठा पाचन काढ़ा','पाठा पचन काढा','Patha Kwatha','decoction','diarrhea_and_digestive_support','1) Take dried Patha roots. 2) Cut into small pieces and boil with water. 3) Reduce to kwatha volume and filter.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily as per advice","child":"only if prescribed"}','after_food','plain','Patha is used in Atisara, Grahani and certain fevers; usually combined with herbs like Kutaja/Mustaka.','2025-12-01 17:38:56',NULL,'ayurveda',37);
INSERT INTO preparations VALUES(71,'Shati Digestive Powder','शाठी पाचन चूर्ण','शाठी पचन चूर्ण','Shati Churna','powder','digestive_and_antiemetic_support','1) Clean and dry Shati rhizomes. 2) Powder to fine churna. 3) Store in airtight container.','grinder;sieve;airtight_jar','20–30 minutes.','Close to rhizome weight.','Store cool and dry.','Few months.','{"adult":"500–1000 mg once or twice daily","child":"only under guidance"}','after_food','with_honey_or_lukewarm_water','Shati is aromatic rhizome used for nausea and digestive issues; dose adjusted to Pitta status.','2025-12-01 17:38:56',NULL,'ayurveda',38);
INSERT INTO preparations VALUES(72,'Daruharidra Decoction','दारुहरिद्रा काढ़ा','दारुहरिद्रा काढा','Daruharidra Kwatha','decoction','eye_and_gut_support','1) Use stem bark pieces of Daruharidra. 2) Boil with water to kwatha strength. 3) Filter; internal use is in small doses, and cooled decoction sometimes used externally near eyes as per classical guidance.','pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily internally under supervision","child":"only if prescribed"}','after_food','plain','Berberine-rich bark used for infections and eye/gut issues; modern drug interactions must be considered.','2025-12-01 17:38:56',NULL,'ayurveda',39);
INSERT INTO preparations VALUES(73,'Chirayata Bitter Tea','चिरायता कड़वी चाय','चिरायता कडू चहा','Kirata Tikta Phanta','herbal_tea','fever_and_liver_support','1) Take small quantity of dried Chirayata herb. 2) Steep in hot water for 10–15 minutes. 3) Strain and drink slowly.','cup;strainer','10–15 minutes.','One cup.','Use fresh.','Same-day.','{"adult":"20–40 ml once or twice daily due to strong bitterness","child":"only under strict supervision"}','before_food_or_as_directed','plain','Very bitter hepatic and antipyretic herb; excessive usage is avoided.','2025-12-01 17:38:56',NULL,'ayurveda',40);
INSERT INTO preparations VALUES(74,'Galangal Digestive Tea','कुलंजन पाचन चाय','कुलंजन पचन चहा','Kulanjan Phanta','herbal_tea','digestive_and_respiratory_support','1) Slice dried Galangal rhizome. 2) Boil or steep in hot water for several minutes. 3) Strain and sip warm.','cup_or_pot;strainer','10–15 minutes.','One cup.','Use fresh.','Same-day.','{"adult":"one cup once or twice daily after food","child":"small amount only if suitable"}','after_meals','as_is','Warming rhizome used in cough, indigestion and voice issues; Pitta aggravation needs monitoring.','2025-12-01 17:38:56',NULL,'ayurveda',41);
INSERT INTO preparations VALUES(75,'Nagarmotha Digestive Decoction','नागरमोथा पाचन काढ़ा','नागरमोथा पचन काढा','Mustaka/Nagarmotha Kwatha','decoction','diarrhea_and_fever_support','1) Use dried tubers of Nagarmotha. 2) Crush and boil in water till reduced. 3) Filter and take warm.','pot;crusher;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily under guidance","child":"only under pediatric supervision"}','after_meals','plain','Very similar action to Mustaka; used in diarrhea, fever and digestive complaints.','2025-12-01 17:38:56',NULL,'ayurveda',42);
INSERT INTO preparations VALUES(76,'Talispatra Cough Decoction','तालिसपत्र खांसी काढ़ा','तालीसपत्र खोकला काढा','Talispatra Kwatha','decoction','respiratory_support','1) Use dried leaves of Talispatra. 2) Boil in water and reduce. 3) Filter and consume lukewarm.','pot;strainer','15–20 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily as supportive cough remedy","child":"only if prescribed"}','after_food','plain','Aromatic leaf used in cough, cold and asthma formulations.','2025-12-01 17:38:56',NULL,'ayurveda',43);
INSERT INTO preparations VALUES(77,'Pushkarmoola Decoction','पुष्करमूल काढ़ा','पुष्करमुळ काढा','Pushkaramoola Kwatha','decoction','respiratory_and_cardiac_support','1) Take dried Pushkarmoola roots. 2) Prepare coarse pieces and boil with water. 3) Filter and use warm.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily under supervision","child":"only under pediatric specialist"}','after_food','plain','Classical herb for breathlessness and certain cardiac complaints; always used with close monitoring.','2025-12-01 17:38:56',NULL,'ayurveda',44);
INSERT INTO preparations VALUES(78,'Black Nightshade Leaf Decoction','माकोय पत्ती काढ़ा','भुई भोपळा पानांचा काढा','Kakamachi Kwatha','decoction','liver_and_skin_support','1) Use correctly identified Black Nightshade leaves and tender aerial parts. 2) Boil in water and reduce moderately. 3) Filter and administer in small supervised doses only.','pot;strainer','15–20 minutes.','60–80 ml.','Use fresh.','Same-day.','{"adult":"10–20 ml once or twice daily under expert guidance","child":"generally avoided unless prescribed"}','after_food','plain','Solanum species may be toxic if misidentified or overdosed; this decoction must be supervised.','2025-12-01 17:38:57',NULL,'ayurveda',45);
INSERT INTO preparations VALUES(79,'Vidarikand Milk Tonic','विदारीकंद दूध टॉनिक','विदारीकंद दूध टॉनिक','Vidari Kanda Ksheerapaka','medicated_milk','rasayana_and_reproductive_support','1) Use dried Vidarikand tuber powder. 2) Boil with milk and water as ksheerapaka. 3) Reduce and serve warm.','pan;stirrer','20–30 minutes.','One or two servings.','Use fresh.','Same-day.','{"adult":"50–100 ml once or twice daily as advised","child":"only under specialist supervision"}','morning_or_evening','as_is','Vidarikand is sweet, cooling Rasayana; useful in debility and reproductive issues when indicated.','2025-12-01 17:38:57',NULL,'ayurveda',46);
INSERT INTO preparations VALUES(80,'Karkatashringi Cough Powder','कर्कटश्रृंगी खांसी चूर्ण','कर्कटश्रृंगी खोकला चूर्ण','Karkatashringi Churna','powder','cough_support','1) Clean dried Karkatashringi galls. 2) Powder to fine churna. 3) Store airtight.','grinder;sieve;airtight_jar','20–30 minutes.','Close to gall weight.','Store cool and dry.','Few months.','{"adult":"500–1000 mg with honey 2–3 times daily as advised","child":"smaller doses only under supervision"}','after_food','with_honey','Classical cough remedy often combined with Vasa, Pippali, etc.','2025-12-01 17:38:57',NULL,'ayurveda',47);
INSERT INTO preparations VALUES(81,'Kalijiri Metabolic Powder','कलिजीरी चूर्ण','कलिजीरी चूर्ण','Kalajiri Churna','powder','metabolic_and_digestive_support','1) Clean Kalijiri seeds. 2) Lightly roast if desired and grind to powder. 3) Store in airtight jar.','pan;grinder;airtight_jar','15–20 minutes.','Close to seed weight.','Store cool and dry.','1–2 months.','{"adult":"1–3 g daily in divided doses as guided","child":"use only under guidance"}','before_meals_or_as_directed','with_lukewarm_water','Used in some classical/regional anti-obesity and metabolic formulations.','2025-12-01 17:38:57',NULL,'ayurveda',48);
INSERT INTO preparations VALUES(82,'Sariva Sharbat','सारिवा शरबत','सारिवा शरबत','Sariva Panaka','syrup','blood_and_cooling_support','1) Soak Sariva root chips in water, boil gently and reduce. 2) Add sugar to form light syrup. 3) Strain and bottle; dilute in water before drinking.','pot;strainer;bottles;spoon','40–60 minutes.','Several servings.','Refrigerate after cooling.','Few weeks if stored hygienically.','{"adult":"10–20 ml syrup diluted in water once or twice daily","child":"5–10 ml diluted if suitable"}','in_hot_season','diluted_in_cool_water','Sariva is classic Rakta-pitta cooling herb; sugar load considered in metabolic disorders.','2025-12-01 17:38:57',NULL,'ayurveda',49);
INSERT INTO preparations VALUES(83,'Vriddhadaru Tonic Decoction','वृद्धदारु टॉनिक काढ़ा','वृद्धदारू टॉनिक काढा','Vriddhadaru Kwatha','decoction','reproductive_and_vata_support','1) Take dried Vriddhadaru root bark. 2) Boil with water as kwatha. 3) Filter and use warm.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily as advised","child":"only under specialist guidance"}','morning_and/or_evening','with_milk_or_as_directed','Referenced as supportive herb in male reproductive and Vata conditions.','2025-12-01 17:38:57',NULL,'ayurveda',50);
INSERT INTO preparations VALUES(84,'Pashanbhed Stone Decoction','पाषाणभेद किडनी स्टोन काढ़ा','पाषाणभेद मूत्रमार्ग काढा','Pashanbheda Kwatha','decoction','urinary_stone_support','1) Use rhizomes of Pashanbhed cut into pieces. 2) Boil in water and reduce. 3) Filter and use warm in small doses.','pot;strainer;knife','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily under urology and Ayurvedic guidance","child":"only under pediatric supervision"}','after_food','plain','Classical supportive herb in renal calculi; not a replacement for surgical/urological interventions when needed.','2025-12-01 17:38:57',NULL,'ayurveda',51);
INSERT INTO preparations VALUES(85,'Ripe Mango Digestive Drink','पका आम पाचन पेय','पिकलेल्या आंब्याचे पचन पेय','Amra Phala Rasa (dietary)','medicated_food','digestive_and_nourishing_support','1) Take ripe Mango pulp, remove fibers and seeds. 2) Blend with small amount of water or buttermilk as per constitution. 3) Serve fresh in moderate quantity.','knife;blender;strainer_optional','10–15 minutes.','2–3 servings.','Use fresh; short refrigeration only.','Same-day.','{"adult":"one glass once daily in season if suitable","child":"small quantity adjusted to age"}','with_or_between_meals','as_is_or_with_diluted_buttermilk','Ripe Mango is heavy but nourishing; quantity adjusted per Agni and Prakriti.','2025-12-01 17:38:57',NULL,'ayurveda',52);
INSERT INTO preparations VALUES(86,'Bakuchi External Oil','बावची बाह्य तेल','बावची बाह्य तेल','Bakuchi Taila (simplified)','medicated_oil_external','vitiligo_and_skin_support_external','1) Soak Bakuchi seeds in suitable medium, then boil with base oil (like sesame) as per classical taila paka. 2) Filter and store. 3) Apply thinly on depigmented patches as advised and avoid sun overexposure.','oil_pan;filter_cloth;bottle','1–2 hours including boiling and cooling.','Depends on oil volume.','Store in cool, dark place.','Few months.','{"adult":"external application in tiny amount as prescribed","child":"only under specialist dermatology/Ayurveda care"}','external_use_only','none','Bakuchi is photosensitizing; improper use can cause burns—strict specialist supervision is required.','2025-12-01 17:38:57',NULL,'ayurveda',53);
INSERT INTO preparations VALUES(87,'Vacha Fine Powder','वचा बारीक चूर्ण','वचा बारीक चूर्ण','Vacha Churna','powder','speech_and_neuro_support_small_dose','1) Clean and dry Sweet Flag rhizomes. 2) Powder very finely and sieve. 3) Store airtight. 4) Use only in very small doses as per expert advice.','grinder;fine_sieve;airtight_jar','20–30 minutes.','Close to rhizome weight.','Store cool and dry.','Few months.','{"adult":"tiny pinch (50–125 mg) internally or as per nasya/prayoga by physician","child":"only under pediatric specialist supervision"}','as_directed','with_honey_or_ghee','Vacha is potent, with CNS effects; excessive use or wrong species may be toxic.','2025-12-01 17:38:57',NULL,'ayurveda',54);
INSERT INTO preparations VALUES(88,'Betel Digestive Mouth Pack','पान पाचन पूड़','पान पचन पान','Tambula (non-tobacco)','medicated_food','digestive_and_freshness_support','1) Take tender Betel leaf, wash and dry. 2) Add small amount of fennel, cardamom, clove, coconut etc., without tobacco or lime. 3) Fold and chew after meals if suitable.','knife;plate','5–10 minutes.','1–2 mouthful packs.','Best used fresh.','Same-day.','{"adult":"one mild pack after heavy meal occasionally","child":"generally avoided"}','after_meals','chewed_and_spat_or_swallowed_as_per_custom','Traditional non-tobacco betel chewing aids digestion but can still irritate mucosa if overused.','2025-12-01 17:38:57',NULL,'ayurveda',55);
INSERT INTO preparations VALUES(89,'Tejpatra Herbal Digestive Tea','तेजपत्ता हर्बल पाचन चाय','तामालपत्र हर्बल पचन चहा','Tamala Patra Phanta','herbal_tea','digestive_support','1) Tear Indian Bay Leaf into pieces. 2) Steep in hot water for 5–10 minutes. 3) Strain and sip warm after meals.','cup;strainer','10–15 minutes.','One cup.','Use fresh.','Same-day.','{"adult":"one cup after heavy meal","child":"not routine; small quantity only if suitable"}','after_meals','as_is','Aromatic tea useful for gas and heaviness.','2025-12-01 17:38:57',NULL,'ayurveda',56);
INSERT INTO preparations VALUES(90,'Hibiscus Hair Rinse','गुड़हल केश धुलाई काढ़ा','जास्वंद केस धुण्याचा काढा','Japa Pushpa Kashaya (external)','decoction','hair_support_external','1) Boil Hibiscus flowers and leaves in water until lightly reduced and slimy. 2) Cool to lukewarm. 3) Use as hair/scalp rinse before or after gentle shampoo.','pot;strainer;bowl','20–30 minutes.','Sufficient for one or two rinses.','Use fresh.','Same-day.','{"adult":"external hair rinse 1–2 times/week","child":"external use if suitable"}','external_use_only','none','Hibiscus rinse is popular for hair fall/dandruff support; part of broader hair-care regimen.','2025-12-01 17:38:57',NULL,'ayurveda',57);
INSERT INTO preparations VALUES(91,'Mexican Poppy External Paste','सत्यानाशी बाह्य लेप','सत्यानाशी बाह्य लेप','Satyanshi Lepa (folk)','paste','skin_support_external_only','1) Prepare paste from leaves/latex of Mexican Poppy ONLY if explicitly indicated and under expert guidance. 2) Apply carefully on localized warts or lesions. 3) Remove within advised time and wash thoroughly.','mortar_and_pestle;gloves;bowl','10–15 minutes to prepare.','Small quantity.','Use immediately; do not store.','Single-use or same-day.','{"adult":"external spot application only under strict supervision","child":"generally avoided"}','external_use_only','none','Plant is potentially toxic; internal use is avoided and external use must be very cautious.','2025-12-01 17:38:57',NULL,'ayurveda',58);
INSERT INTO preparations VALUES(92,'Arka Latex External Application','आर्क क्षीर बाह्य उपयोग','आर्क क्षीर बाह्य उपयोग','Arka Ksheera Prayoga (external)','latex_external','wart_and_skin_lesion_support_external','1) Collect minute quantity of Arka latex carefully with gloves. 2) Touch only on wart/corn as per classical guidance. 3) Avoid contact with normal skin, eyes or mucosa; wash thoroughly after time.','gloves;applicator_stick;water_for_wash','Few minutes to apply.','Drop-level quantity.','Use immediately.','Single-use only.','{"adult":"external spot application only under specialist supervision","child":"generally avoided"}','external_use_only','none','Arka latex is irritant and potentially toxic; used traditionally on warts/corns with extreme caution.','2025-12-01 17:38:57',NULL,'ayurveda',59);
INSERT INTO preparations VALUES(93,'Datura External Pain Oil','धतूरा बाह्य दर्द तेल','धोत्रा बाह्य वेदना तेल','Dhattura Taila (external)','medicated_oil_external','pain_and_vata_support_external','1) Use small quantity of Datura leaves/seeds processed in oil under classical taila preparation with safeguards. 2) Filter and store. 3) Apply thinly on painful joints/muscles externally; do not use on broken skin.','oil_pan;filter_cloth;bottles','1–2 hours including heating and cooling.','Depends on oil volume.','Store in cool, dark place.','Few months.','{"adult":"external massage in thin layer under supervision","child":"usually avoided"}','external_use_only','none','Datura is highly toxic if ingested; Arka/Datura oils are strictly external and physician-supervised only.','2025-12-01 17:38:57',NULL,'ayurveda',60);
INSERT INTO preparations VALUES(94,'Erect Boerhavia Decoction','एरैक्ट बोर्हाविया काढ़ा','उभा बोर्हाविया काढा','Punarnava Prakar Kwatha','decoction','renal_and_edema_support','1) Use roots/aerial parts of Erect Boerhavia similar to Punarnava. 2) Boil with water and reduce. 3) Filter and use under guidance.','pot;strainer','20–30 minutes.','60–100 ml.','Use fresh.','Same-day.','{"adult":"15–30 ml once or twice daily as advised","child":"only under supervision"}','morning_or_evening','plain','Related species used similarly to Punarnava for edema and urinary issues; species ID is important.','2025-12-01 17:38:57',NULL,'ayurveda',61);
INSERT INTO preparations VALUES(95,'Bhringraj Hair Oil','भृंगराज केश तेल','भृंगराज केस तेल','Bhringaraja Taila','medicated_oil_external','hair_and_scalp_support','1) Prepare Bhringraj juice or decoction. 2) Cook with base oil and suitable kalka (pulp) in classical taila paka. 3) Filter and store. 4) Apply to scalp and hair roots.','oil_pan;filter_cloth;bottles','1–2 hours.','Depends on oil volume.','Store in closed bottles away from heat.','Few months.','{"adult":"scalp massage 2–3 times/week","child":"external use if suitable"}','external_use_only','none','Highly popular oil for hair fall and early greying support.','2025-12-01 17:38:57',NULL,'ayurveda',62);
INSERT INTO preparations VALUES(96,'Ram Tulsi Herbal Tea','राम तुलसी हर्बल चाय','राम तुळस हर्बल चहा','Tulasi Phanta','herbal_tea','respiratory_and_immunity_support','1) Take fresh Ram Tulsi leaves, wash and lightly crush. 2) Pour hot water over and cover for 5–10 minutes. 3) Strain and sip warm.','cup;strainer','10–15 minutes.','One cup.','Use fresh.','Same-day.','{"adult":"one cup 1–2 times/day in cold/cough seasons","child":"smaller quantity if suitable"}','morning_and/evening','as_is','Sacred Tulsi species used in colds, cough and mild anxiety.','2025-12-01 17:38:57',NULL,'ayurveda',63);
INSERT INTO preparations VALUES(97,'Sweet Basil Herbal Tea','स्वीट बेसिल हर्बल चाय','स्वीट बेसिल हर्बल चहा','Tulasi Videshi Phanta (modern)','herbal_tea','digestive_and_relax_support','1) Use fresh or dried Sweet Basil leaves. 2) Steep in hot water for 5–10 minutes. 3) Strain and drink warm.','cup;strainer','10–15 minutes.','One cup.','Use fresh.','Same-day.','{"adult":"one cup once or twice daily as relaxing tea","child":"small amount, if suitable"}','evening_or_after_meals','as_is','Parallel to Tulsi but milder; used for digestion and mild relaxation.','2025-12-01 17:38:57',NULL,'ayurveda',64);
INSERT INTO preparations VALUES(98,'Pudina Digestive Water','पुदीना पाचन जल','पुदिना पचन पाणी','Pudina Jala (folk)','herbal_water','digestive_and_cooling_support','1) Crush fresh Field Mint leaves lightly. 2) Infuse in potable water for some time. 3) Strain and drink in small amounts.','jug;strainer','15–30 minutes infusion.','Several glasses.','Keep covered and use within the day.','Same-day use.','{"adult":"small glass 1–2 times/day in hot season","child":"smaller quantity if suitable"}','between_meals','as_is','Mint water aids digestion and cooling; avoid in very cold constitution or reflux if worsened.','2025-12-01 17:38:57',NULL,'ayurveda',65);
INSERT INTO preparations VALUES(99,'Peppermint Digestive Tea','पेपरमिंट पाचन चाय','पेपरमिंट पचन चहा','Peppermint Phanta','herbal_tea','digestive_and_spasm_support','1) Take fresh/dried Peppermint leaves. 2) Steep in hot water for 5–10 minutes. 3) Strain and sip warm.','cup;strainer','10–15 minutes.','One cup.','Use fresh.','Same-day.','{"adult":"one cup after meals for gas/spasm relief","child":"small quantity only if suitable"}','after_meals','as_is','Peppermint tea can relieve spasm but may worsen reflux in some individuals.','2025-12-01 17:38:57',NULL,'ayurveda',66);
INSERT INTO preparations VALUES(100,'Dill Seed Digestive Tea','सोया बीज पाचन चाय','शेप बी पचन चहा','Soya/Shepa Phanta','herbal_tea','infant_colic_and_digestive_support','1) Lightly crush Dill seeds. 2) Steep in hot water for 5–10 minutes. 3) Strain and cool before use.','cup;strainer','10–15 minutes.','One cup.','Use fresh.','Same-day.','{"adult":"one cup after meals as needed","child":"few teaspoons of cooled tea for infant colic only on pediatric advice"}','after_meals','as_is','Dill seed tea is popular for colic; exact infant dosing must be guided by pediatrician.','2025-12-01 17:38:57',NULL,'ayurveda',67);
INSERT INTO preparations VALUES(101,'Garlic Rasayana Paste','लहसुन रसायन लेप्य','लसूण रसायन पेस्ट','Lashuna Rasayana (simplified)','paste','cardio_and_digestive_support','1) Peel Garlic cloves and pound to paste. 2) Gently fry in ghee until mild aroma and remove from flame. 3) Use small quantity with food.','pan;spatula;mortar_and_pestle','15–20 minutes.','Few tablespoons.','Refrigerate for short time if needed.','2–3 days if refrigerated.','{"adult":"1–3 small cloves worth per day depending on tolerance","child":"minimal or none unless advised"}','with_main_meal','as_part_of_food','Garlic is cardioprotective and digestive but can aggravate Pitta and cause odor/reflux.','2025-12-01 17:38:57',NULL,'ayurveda',68);
INSERT INTO preparations VALUES(102,'Onion Warming Poultice','प्याज गरम पोटली','कांदा गरम पट्टी','Palandu Lepa (external)','paste','respiratory_and_joint_support_external','1) Chop Onion and lightly warm in pan (optional with little oil). 2) Wrap in clean cloth as poultice. 3) Apply warm (not hot) over chest/back or joint under guidance.','pan;cloth;spatula','15–20 minutes.','One or two poultices.','Use immediately; do not store.','Single-use.','{"adult":"external application for 15–20 minutes at a time","child":"only under careful supervision to avoid burns"}','external_use_only','none','Traditional warming poultice for congestion and aches; temperature must be carefully checked.','2025-12-01 17:38:57',NULL,'ayurveda',69);
INSERT INTO preparations VALUES(103,'Sharbat-e-Ailwa','शरबत-ए-एलोवेरा','शरबत-ए-कोरफड','Sharbat-e-Ailwa','syrup','cooling_and_digestive_support','1) Extract fresh Aloe Vera gel. 2) Blend with water. 3) Cook gently with sugar until thin syrup consistency. 4) Cool and bottle.','blender;pan;strainer;bottle','30–40 minutes','1–2 bottles','Refrigerate after bottling.','1–2 months refrigerated','{"adult":"15–25 ml diluted in water","child":"mildly diluted as guided"}','before_food_or_as_drink','cold_water','Traditional cooling syrup used in summer months; avoid in diarrhea.','2025-12-01 18:46:32',NULL,'unani',144);
INSERT INTO preparations VALUES(104,'Majoon-e-Akhrot','माजून-ए-अखरोट','माजून-ए-अक्रोड','Majoon-e-Akhrot','electuary','nutritive_and_joint_support','1) Grind Walnut kernels to paste. 2) Add honey and mild warming spices. 3) Mix to semisolid electuary. 4) Store airtight.','grinder;mixing_bowl;jar','30–45 minutes','50grams to 100grams','Small jar','1–2 months','{"adult":"1 teaspoon daily","child":"tiny amount under guidance"}','morning','lukewarm_milk_optional','Used as nutritive electuary in weakness and joint discomfort.','2025-12-02 15:10:58',NULL,'unani',204);
INSERT INTO preparations VALUES(105,'Majoon-e-Maghz-e-Kadu','माजून-ए-मग़ज़-ए-कद्दू','माजून-ए-कद्दू बिया','Majoon-e-Maghz-e-Kadu','electuary','urinary_and_male_support_mild','1) Grind Pumpkin seeds to paste. 2) Mix with honey. 3) Add mild spices if suitable. 4) Store airtight.','grinder;mixing_bowl;jar','20–30 minutes','50grams to 100grams','Small jar','1–2 months','{"adult":"1 teaspoon daily","child":"few drops under guidance"}','morning','lukewarm_water','Traditional nutritive electuary supporting mild urinary tract wellbeing.','2025-12-02 15:10:58',NULL,'unani',205);
INSERT INTO preparations VALUES(106,'Murabba-e-Kharbooja','मुरब्बा-ए-खरबूजा','मुरब्बा-ए-खरबूज','Murabba-e-Kharbooja','conserve','nutritive_cooling_support','1) Cut Muskmelon pieces. 2) Cook in sugar syrup until translucent. 3) Cool and bottle.','pan;sieve;jar','60–90 minutes','10–15 pieces','Small jar','1–2 months','{"adult":"1–2 small pieces","child":"half piece if suitable"}','morning','as_is','Cooling and mildly laxative Unani preserve.','2025-12-02 15:10:58',NULL,'unani',206);
INSERT INTO preparations VALUES(107,'Arnica 30C Oral Globules','आर्निका 30C गोलियां','आर्निका 30C गोळ्या','Arnica montana 30C','globules','trauma_and_bruise_support','Prepared industrially as per homeopathic pharmacopeia; in practice patient takes medicated sugar globules as per physician advice.','homeopathic_manufacturing_unit','industrial','bottle','Store in cool, dry, dark place, away from strong odours.','3–5_years','{"adult":"3–5 globules once or twice daily as advised by homeopathic physician","child":"lower dose as advised"}','as_directed_by_physician','none','Used as a classic homeopathic trauma remedy for bruises and soreness in appropriate indications.','2025-12-02 16:49:49',NULL,'homeopathy',213);
