INSERT INTO preparations VALUES(132,'Gudmar Kadha','गुडमार का काढ़ा','गुडमार काढा','Meshashringi Kwatha','decoction','metabolic_support','1) Take 5–7 fresh or dried Gudmar leaves (Meshashringi / Gymnema sylvestre). 2) Rinse thoroughly. 3) Add to 200–250 ml water. 4) Boil on low flame until reduced to half (approx. 100–120 ml). 5) Strain and use warm.','["steel_pot","strainer","measuring_cup","stove"]','10–15 minutes boiling + cooling time','~100 ml decoction','Use fresh; do not store for long.','same_day_fresh','{"adult":"30–50 ml once or twice daily", "child":"use only under practitioner supervision"}','before_food','lukewarm_water','Traditional Ayurveda–based decoction useful as supportive care for sugar and metabolic balance. Should not replace prescribed diabetic medication. Monitor sugar levels regularly.','2025-12-09 14:47:02',NULL,'ayurveda',108);
